      for(const key of ['page_properties','panel_properties','hidden_properties'])draft[key]=draft[key].filter(value=>value!==id);
      draft[mode==='hidden'?'hidden_properties':originalPlacement||`${draft.property_group_placement}_properties`].push(id);
      if(mode==='hidden')draft.standalone_properties=draft.standalone_properties.filter(value=>value!==id);
