const INLINE_COLOR_NAMES = [["default","기본"],["gray","회색"],["brown","갈색"],["orange","주황색"],
  ["yellow","노란색"],["green","초록색"],["blue","파란색"],["purple","보라색"],["pink","분홍색"],["red","빨간색"]];

function inlineFormatContextCurrent(context) {
  return Boolean(context && State.inlineFormat === context && context.saved === State.inlineSelection
    && context.scope === pageReferenceDisplayScope() && inlineToolbarSelectionCurrent(context.saved));
}

function closeInlineFormatPopover(restoreFocus = false) {
  const context = State.inlineFormat, restore = restoreFocus && inlineFormatContextCurrent(context);
  State.inlineFormat = null;
  $("#inlineFormatPopover").hidden = true;
  $('#inlineToolbar [data-inline-format="type"]')?.setAttribute("aria-expanded", "false");
  $('#inlineToolbar [data-inline-format="color"]')?.setAttribute("aria-expanded", "false");
  if (restore) context.trigger.focus({preventScroll:true});
  updateInlineSelectionHighlight();
}

function positionInlineFormatPopover() {
  const context = State.inlineFormat;
  if (!context) return;
  const anchor = {get isConnected() {return inlineFormatContextCurrent(context);},getBoundingClientRect() {
    const r=context.trigger.getBoundingClientRect();
    return context.kind === "color" ? {left:r.left-8,right:r.right,top:r.top,bottom:r.bottom}
      : {left:r.left+4,right:r.right-4,top:r.top,bottom:r.bottom};
  }};
  window.NotionUiInteraction.place($("#inlineFormatPopover"), anchor, context.kind === "color" ? "below" : "right");
}

function openInlineFormatPopover(kind) {
  if (!inlineToolbarSelectionCurrent()) return;
  closeInlineLinkPopover();closeInlineFormatPopover();
  const context = {kind,saved:State.inlineSelection,scope:pageReferenceDisplayScope(),
    trigger:$(`#inlineToolbar [data-inline-format="${kind}"]`)};
  State.inlineFormat = context;
  const pop = $("#inlineFormatPopover");
  pop.dataset.kind = kind;pop.setAttribute("aria-label", kind === "color" ? "텍스트 색상" : "블록 유형 전환");
  if (kind === "type") {
    const types=["paragraph","heading1","heading2","heading3","heading4","child_page","bullet","numbered","todo","toggle",
      "code","quote","callout","equation","toggle_heading1","toggle_heading2","toggle_heading3","toggle_heading4",
      "layout_columns_2","layout_columns_3","layout_columns_4","layout_columns_5"];
    pop.innerHTML = types.map(type => {
      const [icon,label]=blockTypeMeta(type),current=State.pageData.blocks[context.saved.index].type===type;
      return `<button type="button" role="menuitem" class="inline-format-type" data-inline-type="${type}" aria-label="${escapeAttr(label)}"><span aria-hidden="true">${icon}</span><span>${escapeHtml(label)}</span><span aria-hidden="true">${current ? "✓" : ""}</span></button>`;
    }).join("");
  } else {
    const start=context.saved.range.startContainer.nodeType===Node.ELEMENT_NODE ? context.saved.range.startContainer : context.saved.range.startContainer.parentElement;
    const cells=(key,only=null)=>`<div class="inline-color-grid">${INLINE_COLOR_NAMES.filter(([name])=>!only || name===only).map(([name,label])=>
      `<button type="button" role="menuitem" data-inline-color="${name}" data-inline-color-key="${key}" aria-label="${label} ${key === "color" ? "텍스트" : "배경"}" aria-checked="${(start.closest(`[data-notion-inline-${key}]`)?.getAttribute(`data-notion-inline-${key}`)||"default")===name}"><span aria-hidden="true" class="color-swatch ${key === "color" ? "text" : "bg"}-${name}">${key === "color" ? "A" : ""}</span></button>`).join("")}</div>`;
    const recent=State.lastInlineColor?.scope===context.scope ? State.lastInlineColor : null;
    pop.innerHTML=(recent ? `<div class="inline-color-label">최근 사용</div>${cells(recent.key,recent.value)}` : "")
      + `<div class="inline-color-label">텍스트 색상</div>${cells("color")}<div class="inline-color-label">배경 색상</div>${cells("background")}`;
  }
  pop.querySelectorAll("button").forEach(button=>{
    button.addEventListener("mousedown",event=>event.preventDefault());
    button.addEventListener("click",()=>{
      if (!inlineFormatContextCurrent(context)) {closeInlineToolbar();return;}
      if (kind === "color") applyInlineColor(button.dataset.inlineColorKey,button.dataset.inlineColor);
      else {
        const type=button.dataset.inlineType,index=context.saved.index;
        const caret=context.saved.range.cloneRange();caret.selectNodeContents(context.saved.editor);caret.setEnd(context.saved.range.endContainer,context.saved.range.endOffset);
        const offset=caret.toString().length;
        closeInlineToolbar();clearBlockSelection();
        if (type==="child_page") void insertChildPageAfter(index,true);
        else if (/^layout_columns_[2-5]$/.test(type)) createColumnLayout(index,Number(type.slice(-1)),"convert");
        else changeBlockType(index,type,offset);
      }
    });
  });
  pop.hidden=false;context.trigger.setAttribute("aria-expanded","true");positionInlineFormatPopover();
  pop.focus({preventScroll:true});updateInlineSelectionHighlight();
}

function applyInlineColor(key,value) {
  const context=State.inlineFormat;
  if (!inlineFormatContextCurrent(context)) {closeInlineToolbar();return;}
  if (!["color","background"].includes(key) || !INLINE_COLOR_NAMES.some(([name])=>name===value)) return;
  closeInlineFormatPopover();
  const saved=restoreInlineSelection();if(!saved)return;
  setInlineSelectionColor(saved,key,value);
  syncEditorBlock(saved.editor,State.pageData.blocks[saved.index]);
  State.lastInlineColor={key,value,scope:context.scope};markDirty();updateInlineToolbar();closeInlineToolbar(true);
}

function setInlineSelectionColor(saved,key,value) {
  const attribute=`data-notion-inline-${key}`,fragment=saved.range.extractContents();
  fragment.querySelectorAll(`[${attribute}]`).forEach(span=>{span.removeAttribute(attribute);span.style.removeProperty(key === "color" ? "color" : "background-color");});
  const span=document.createElement("span");span.setAttribute(attribute,value);
  span.style[key === "color" ? "color" : "backgroundColor"]=value === "default"
    ? key === "color" ? "var(--text)" : "transparent" : `var(--block-${key === "color" ? "text" : "bg"}-${value})`;
  span.appendChild(fragment);saved.range.insertNode(span);
  // Split the old annotation around the selection so a background reset cannot
  // inherit paint from its former enclosing span. Other inline marks stay intact.
  for(let parent=span.parentElement;parent && parent!==saved.editor;parent=parent.parentElement) {
    const old=parent.getAttribute(attribute);if(!old)continue;
    const walker=document.createTreeWalker(parent,NodeFilter.SHOW_TEXT),outside=[];
    for(let node=walker.nextNode();node;node=walker.nextNode())
      if(node.nodeValue && !span.contains(node) && node.parentElement.closest(`[${attribute}]`)===parent)outside.push(node);
    outside.forEach(node=>{
      const wrapper=document.createElement("span");wrapper.setAttribute(attribute,old);
      wrapper.style[key === "color" ? "color" : "backgroundColor"]=old === "default"
        ? key === "color" ? "var(--text)" : "transparent" : `var(--block-${key === "color" ? "text" : "bg"}-${old})`;
      node.replaceWith(wrapper);wrapper.appendChild(node);
    });
    parent.removeAttribute(attribute);parent.style.removeProperty(key === "color" ? "color" : "background-color");
  }
  const range=document.createRange();range.selectNodeContents(span);getSelection().removeAllRanges();getSelection().addRange(range);
  saved.range=range.cloneRange();
  return span;
}

function handleInlineFormatKeydown(event) {
  if(event.isComposing || event.keyCode===229)return;
  if(event.key==="Escape" || event.key==="ArrowLeft" && State.inlineFormat?.kind==="type") {
    event.preventDefault();event.stopPropagation();closeInlineFormatPopover(true);return;
  }
  if(event.ctrlKey || event.metaKey || event.altKey)return;
  const items=[...$("#inlineFormatPopover").querySelectorAll("button")],current=items.indexOf(document.activeElement);
  if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight","Home","End"].includes(event.key)) {
    event.preventDefault();event.stopPropagation();
    const grid=State.inlineFormat?.kind==="color",delta=event.key==="ArrowDown" ? grid ? 5 : 1 : event.key==="ArrowUp" ? grid ? -5 : -1 : event.key==="ArrowLeft" ? -1 : 1;
    const next=event.key==="Home" ? 0 : event.key==="End" ? items.length-1 : current<0 ? delta<0 ? items.length-1 : 0 : (current+delta+items.length)%items.length;
    items[next]?.focus({preventScroll:true});
  } else if(event.key==="Enter" && current<0) {event.preventDefault();event.stopPropagation();items[0]?.click();}
}

function toggleInlineCode() {
  const selection = window.getSelection();
  const editor = document.activeElement?.closest?.(".block-editor");
  if (!selection?.rangeCount || selection.isCollapsed || !editor || !editor.contains(selection.anchorNode)) return;
  const range = selection.getRangeAt(0);
  const startElement = range.startContainer.nodeType === Node.ELEMENT_NODE
    ? range.startContainer
    : range.startContainer.parentElement;
  const existing = startElement?.closest?.("code");
  if (existing && editor.contains(existing) && existing.contains(range.endContainer)) {
    const parent = existing.parentNode;
    while (existing.firstChild) parent.insertBefore(existing.firstChild, existing);
    existing.remove();
  } else {
    const code = document.createElement("code");
    code.appendChild(range.extractContents());
    range.insertNode(code);
    const nextRange = document.createRange();
    nextRange.selectNodeContents(code);
    selection.removeAllRanges();
    selection.addRange(nextRange);
  }
  const index = Number(editor.closest(".block-row")?.dataset.index);
  syncEditorBlock(editor, State.pageData?.blocks?.[index]);
  markDirty();
}

function insertSoftBreak(editor, block) {
  if (!document.execCommand("insertLineBreak", false, null)) {
    document.execCommand("insertHTML", false, "<br>");
  }
  syncEditorBlock(editor, block);
  markDirty();
}

function scrollToLocationBlock() {
  const hash = decodeURIComponent(location.hash || "");
  if (!hash.startsWith("#block-")) return;
  const target = document.getElementById(hash.slice(1));
  if (!target) return;
  target.scrollIntoView({ block: "center" });
  target.classList.add("block-linked");
  setTimeout(() => target.classList.remove("block-linked"), 1400);
}

function applyMarkdownShortcut(editor, block, index) {
  const shortcut = EditorCore.markdownShortcut(editorPlainText(editor));
  if (!shortcut) return false;
  try {
    State.pageData.blocks=window.NotionBlockStructure.replace(State.pageData.blocks,index,
      EditorCore.createBlock(shortcut.type,{content:shortcut.content}));
  } catch(error){setStatus(error.message,'error');return false;}
  const targetIndex=State.pageData.blocks.findIndex(item=>item.id===block.id);
  if (shortcut.type === "divider") {
    const next=EditorCore.createBlock("paragraph");
    State.pageData.blocks=window.NotionBlockStructure.insert(State.pageData.blocks,targetIndex,[next]);
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(State.pageData.blocks.findIndex(item=>item.id===next.id), 0);
    return true;
  }
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
  focusBlock(targetIndex, 0);
  return true;
}

function pasteMultilineAt(index, editor, text) {
  const blocks = State.pageData?.blocks || [];
  const block = blocks[index];
  if (!block) return;
  const offset = caretOffset(editor);
  const content = editorPlainText(editor);
  const before = content.slice(0, offset);
  const after = content.slice(offset);
  const pasted = EditorCore.blocksFromPlainText(text);
  if (!pasted.length) return;
  const nextBlock = EditorCore.deepClone(block);
  nextBlock.content = before + pasted[0].content;
  nextBlock.props = nextBlock.props || {};
  delete nextBlock.props.rich_text_html;
  const nextBlocks = blocks.slice();
  nextBlocks[index] = nextBlock;
  const tail = pasted.slice(1);
  if (!tail.length) {
    nextBlock.content += after;
    State.pageData.blocks = nextBlocks;
    markDirty();
    renderBlocks();
    focusBlock(index, before.length + pasted[0].content.length);
    return;
  }
  tail[tail.length - 1].content += after;
  try {
    State.pageData.blocks = window.NotionBlockStructure.insert(nextBlocks,index,tail);
  } catch (error) {setStatus(error.message,'error');return;}
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
  focusBlock(State.pageData.blocks.findIndex(block=>block.id===tail.at(-1).id), tail[tail.length - 1].content.length - after.length);
}

function bindBlockDrag(row, block, index, canEdit) {
  const handle = row.querySelector(".block-handle");
  if (!handle || !canEdit) return;
  handle.draggable = true;
  handle.addEventListener("dragstart", event => {
    const ids = State.selectedBlockIds.has(block.id) ? [...State.selectedBlockIds] : [block.id];
    State.blockDrag = { id: block.id, ids, overId: "", position: "" };
    event.dataTransfer.effectAllowed = event.altKey ? "copyMove" : "move";
    event.dataTransfer.setData("application/x-notion-blocks", JSON.stringify(ids));
    event.dataTransfer.setData("text/plain", block.content || blockTypeMeta(block.type)[1]);
    row.classList.add("dragging");
  });
  // A narrow row may receive dragenter followed immediately by drop. Resolve
  // the destination on entry as well as hover so quick cross-column moves work.
  const previewDrop = event => {
    if (!State.blockDrag.id || State.blockDrag.ids?.includes(block.id)) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = event.altKey ? "copy" : "move";
    const rect = row.getBoundingClientRect();
    const position = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    document.querySelectorAll(".block-row.drop-before, .block-row.drop-after").forEach(item => item.classList.remove("drop-before", "drop-after"));
    row.classList.add(position === "before" ? "drop-before" : "drop-after");
    State.blockDrag.overId = block.id;
    State.blockDrag.position = position;
  };
  row.addEventListener("dragenter", previewDrop);
  row.addEventListener("dragover", previewDrop);
  row.addEventListener("drop", event => {
    if (!State.blockDrag.id || !State.blockDrag.overId) return;
    event.preventDefault();
    const blocks = State.pageData.blocks;
    const draggedIds = State.blockDrag.ids || [State.blockDrag.id];
    const indices = EditorCore.expandBlockSelection(blocks, blocks.map((item,i)=>draggedIds.includes(item.id)?i:-1));
    const target = blocks.findIndex(item => item.id === State.blockDrag.overId);
    if (target < 0 || indices.includes(target)) return;
    try {
      if (event.altKey) {
        if (!databaseStructureMutationAllowed(indices)) return;
        const copies = EditorCore.cloneBlocks(indices.map(i=>blocks[i]), copyEditorBlock);
        State.pageData.blocks = window.NotionBlockStructure.insert(blocks,target,copies,{before:State.blockDrag.position==='before'});
        State.selectedBlockIds = new Set(copies.map(item=>item.id));
      } else {
        const result = window.NotionBlockStructure.moveRelative(blocks,indices,target,State.blockDrag.position);
        if (!result.ids.length) return;
        State.pageData.blocks = result.blocks;
        State.selectedBlockIds = new Set(result.ids);
      }
    } catch (error) {setStatus(error.message,'error');return;}
    State.blockDrag = { id: "", ids: [], overId: "", position: "" };
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
  });
  handle.addEventListener("dragend", () => {
    State.blockDrag = { id: "", ids: [], overId: "", position: "" };
    document.querySelectorAll(".block-row.dragging, .block-row.drop-before, .block-row.drop-after").forEach(item => item.classList.remove("dragging", "drop-before", "drop-after"));
  });
}

function addBlockToColumn(groupId, columnIndex, columnCount, memberIds = null, parentId = null) {
  if (!activePageCanEdit() || !groupId) return;
  const blocks = State.pageData?.blocks || [];
  const members = blocks
    .map((block, index) => ({ block, index }))
    .filter(({ block }) => block.props?.layout_group === groupId && (!memberIds || memberIds.includes(block.id)));
  if (!members.length) return;
  const sameColumn = members.filter(({ block }) => Number(block.props?.layout_column || 0) === columnIndex);
  const nextColumn = members.find(({ block }) => Number(block.props?.layout_column || 0) > columnIndex);
  const lastMember = sameColumn.at(-1);
  const insertAt = sameColumn.length
    ? Math.max(...EditorCore.expandBlockSelection(blocks, [lastMember.index])) + 1
    : (nextColumn?.index ?? members[members.length - 1].index + 1);
  const context = (lastMember || nextColumn || members[0]).block.props || {};
  const block = EditorCore.createBlock("paragraph", {
    props: { indent: context.indent || 0, layout_group: groupId, layout_column: columnIndex, layout_columns: columnCount,
      ...(context.tab_group ? {tab_group:context.tab_group,tab_id:context.tab_id} : {}) },
  });
  const owner = blocks.find(candidate => candidate.id === parentId);
  if (Array.isArray(owner?.props?.children) && owner.props.children.every(id => typeof id === 'string')) {
    const children = owner.props.children;
    const after = lastMember && children.indexOf(lastMember.block.id), before = nextColumn && children.indexOf(nextColumn.block.id);
    children.splice(Number.isInteger(after) && after >= 0 ? after + 1 : Number.isInteger(before) && before >= 0 ? before : children.length, 0, block.id);
  }
  blocks.splice(insertAt, 0, block);
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
  focusBlock(insertAt, 0);
}

function refreshBlockSlashMenu(editor, block, index, row, composing = false) {
  const selection = window.getSelection();
  let offset = caretOffset(editor);
  if (composing && selection?.rangeCount && editor.contains(selection.focusNode)) {
    const range = selection.getRangeAt(0).cloneRange();
    range.selectNodeContents(editor);
    range.setEnd(selection.focusNode, selection.focusOffset);
    offset = Math.max(offset, range.toString().length);
  }
  const slash = window.NotionSlashMenu.trigger(editor.textContent, offset);
  if (slash && (composing || selectionIsCollapsed(editor))) {
    State.slashToken = {...slash, blockId: block.id};
    if (slash.query === "") editor.setAttribute("data-slash-hint", "검색어를 입력하세요");
    else editor.removeAttribute("data-slash-hint");
    if (!$("#blockMenu").hidden && State.menuMode === "slash" && State.slashSourceIndex === index) {
      $("#blockMenu .menu-search").value = slash.query;
      filterBlockMenu(slash.query);
    } else openBlockMenu(index, row, "slash", slash.query);
  } else if (State.menuMode === "slash" && State.slashSourceIndex === index) closeBlockMenu();
  return slash;
}

function finishComposingSlash(event, editor, block, index) {
  if ($("#blockMenu").hidden || State.menuMode !== "slash" || State.slashSourceIndex !== index) return false;
  const key = event.key === "Process" ? event.code : event.key;
  if (!["Enter", "Escape"].includes(key) || event.shiftKey || event.ctrlKey || event.metaKey || event.altKey) return false;
  const row = editor.closest(".block-row");
  const slash = refreshBlockSlashMenu(editor, block, index, row, true);
  if (!slash) return false;
  event.preventDefault();
  event.stopPropagation();
  const html = editor.innerHTML, pageId = State.activePageId;
  // Blur commits the OS preedit before menu actions can replace the editor.
  // Escape's native cancellation must not discard the visible search text.
  editor.blur();
  setTimeout(() => {
    if (!editor.isConnected || State.activePageId !== pageId || !activePageCanEdit()) return;
    editor.innerHTML = html;
    if (editor.dataset.imeComposing === "true") {
      editor.dataset.imeComposing = "false";
      EditorHost.endComposition(block.id || "");
    }
    if (!editor.isConnected) return;
    focusBlock(index, slash.end);
    commitBlockEditorInput(editor, block, index, row);
    if (key === "Escape") closeBlockMenu();
    else activateBlockMenuSelection();
  }, 0);
  return true;
}

function commitBlockEditorInput(editor, block, index, row) {
  syncEditorBlock(editor, block);
  syncSyncedBlockPeers(block, index);
  if (block.type === "equation") {
    markDirty();
    return;
  }
  if (applyMarkdownShortcut(editor, block, index)) return;
  const offset = caretOffset(editor);
  const mention = block.content.slice(0, offset).match(/(?:^|\s)@([^\s@]{0,80})$/);
  if (mention) {
    const query = mention[1] || "";
    openMentionMenu(index, row, query, offset - query.length - 1, offset);
  } else if (State.mention.blockIndex === index) {
    closeMentionMenu();
  }
  refreshBlockSlashMenu(editor, block, index, row);
  markDirty();
  if (State.comments.some(item => !item.parent_id && !item.resolved && item.block_id === block.id))
    renderPageInlineCommentMarkers();
}

function renderBlocks() {
  const root = $("#blocks");
  if (DatabaseViewSettingsOpen && DatabaseViewSettingsOpen.pageId !== State.activePageId)
    DatabaseViewSettingsOpen = null;
  if (pendingLinkedDatePicker && (pendingLinkedDatePicker.pageId !== State.activePageId
      || pendingLinkedDatePicker.workspaceId !== State.navigation.workspaceId
      || pendingLinkedDatePicker.userId !== State.user?.id
      || pendingLinkedDatePicker.navigationSequence !== State.navigation.sequence)) {
    pendingLinkedDatePicker.dismiss();
  }
  // The structural catalog can contain older parent props than the CRDT body.
  // Wait for the complete replay before interpreting or normalizing its tree.
  if (collaborativeEditingActive() && !State.liveCollaboration.crdtReady) {
    dismissDatePickerBeforeRedraw(root);
    if(DatabaseFileActionMenu.toggle && root.contains(DatabaseFileActionMenu.toggle))
      DatabaseFileActionMenu.close?.(false);
    if(DatabaseFileAddMenu.toggle && root.contains(DatabaseFileAddMenu.toggle))
      DatabaseFileAddMenu.close?.(false,false,true);
    root.setAttribute("aria-busy", "true");
    root.textContent = "페이지를 불러오는 중…";
    return;
  }
  root.removeAttribute("aria-busy");
  if (deferDatabaseInputRender(root)) return;
  if (deferSyncedClipboardRender()) return;
  // Keep the active native editor and its IME/undo state alive across unrelated
  // document projections. A blur replays the deferred layout once editing ends.
  if (syncedTextHoldsFocus(root)) { SyncedTextRenderDeferred = true; return; }
  SyncedTextRenderDeferred = false;
  const controlFocus = captureDatabaseControlFocus();
  const openTemplatePopover=root.querySelector('[data-db-template-popover]:popover-open');
  const openTemplateBlockId=openTemplatePopover?.closest('.block-row[data-block-id]')?.dataset.blockId||'';
  const openTemplateActions=openTemplatePopover?.querySelector('[data-db-template-actions]');
  const openTemplateActionFocus=()=>{
    if(document.activeElement?.hasAttribute('data-db-template-edit'))return 'edit';
    if(document.activeElement?.hasAttribute('data-db-template-set-default'))return 'default';
    if(document.activeElement?.hasAttribute('data-db-template-duplicate'))return 'duplicate';
    if(document.activeElement?.hasAttribute('data-db-template-delete'))return 'delete';
    return 'back';
  };
  const openTemplateFocus=openTemplateActions&&!openTemplateActions.hidden
    ? {kind:'actions',id:openTemplateActions.dataset.templateId||'',action:openTemplateActionFocus()}
    :openTemplatePopover?.contains(document.activeElement)
    ? {kind:document.activeElement.hasAttribute('data-db-template-more')?'more'
        :document.activeElement.dataset.dbTemplateEdit?'edit'
        :document.activeElement.hasAttribute('data-db-template-set-default')?'default'
        :document.activeElement.hasAttribute('data-db-template-duplicate')?'duplicate'
        :document.activeElement.hasAttribute('data-db-template-delete')?'delete'
        :document.activeElement.hasAttribute('data-db-template-option')?'option':'create',
      id:document.activeElement.dataset.dbTemplateMore??document.activeElement.dataset.dbTemplateEdit??document.activeElement.dataset.dbTemplateSetDefault
        ??document.activeElement.dataset.dbTemplateDuplicate??document.activeElement.dataset.dbTemplateDelete
        ??document.activeElement.dataset.dbTemplateOption??''}
    : null;
  const previousHourScroll = new Map([...root.querySelectorAll('.block-row[data-block-id] .timeline-block.hour-scale .timeline-scroll')]
    .map(scroll => [scroll.closest('.block-row[data-block-id]')?.dataset.blockId, scroll.scrollLeft]));
  const previousTableScroll = new Map([...root.querySelectorAll('.block-row[data-block-id] .dynamic-table-grid')]
    .filter(scroll=>!scroll.closest('[data-linked-database]'))
    .map(scroll=>[scroll.closest('.block-row[data-block-id]')?.dataset.blockId,scroll.scrollLeft]));
  const previousViewTabsScroll = new Map([...root.querySelectorAll('.block-row[data-block-id] .database-view-tabs')]
    .map(scroll=>[scroll.closest('.block-row[data-block-id]')?.dataset.blockId,scroll.scrollLeft]));
  const previousDateAnchor = activeDatabaseDatePickerAnchor;
  const previousDateBlockId = previousDateAnchor && root.contains(previousDateAnchor)
    && !document.querySelector('.database-date-picker[aria-busy="true"]')
    ? previousDateAnchor.closest('.block-row[data-block-id]')?.dataset.blockId : '';
  const previousDateLinked = Boolean(previousDateBlockId && previousDateAnchor.closest('[data-linked-database]'));
  if (previousDateLinked) pendingLinkedDatePicker = {
    blockId:previousDateBlockId, anchor:previousDateAnchor,
    signature:activeDatabaseDatePickerSignature, version:previousDateAnchor.dataset.dbCellVersion,
    dismiss:activeDatabaseDatePickerDismiss,
    pageId:State.activePageId, workspaceId:State.navigation.workspaceId,
    userId:State.user?.id, navigationSequence:State.navigation.sequence,
  };
  if (!previousDateBlockId || !activeDatabaseDatePickerReanchor) dismissDatePickerBeforeRedraw(root);
  if(DatabaseFileActionMenu.toggle && root.contains(DatabaseFileActionMenu.toggle))
    DatabaseFileActionMenu.close?.(false);
  const fileMenuHadUploadFocus=Boolean(DatabaseFileAddMenu.toggle
    && root.contains(DatabaseFileAddMenu.toggle)
    && document.activeElement?.matches?.('.database-file-menu > .database-file-add'));
  if(DatabaseFileAddMenu.toggle && root.contains(DatabaseFileAddMenu.toggle))
    DatabaseFileAddMenu.close?.(false,false,true);
  root.innerHTML = "";
  window.NotionGridSelection?.syncGutterRows([]);
  State.pageData.blocks = (State.pageData.blocks || []).map(EditorCore.normalizeBlock);
  const blocks = State.pageData.blocks;
  if (!blocks.length) blocks.push(EditorCore.createBlock("paragraph"));
  let fullPageDatabase = blocks.find(block => (
    block.id === State.databaseFullPageBlockId
    && DATABASE_BLOCK_TYPES.has(block.type)
  )) || null;
  if (!fullPageDatabase) State.databaseFullPageBlockId = "";
  applyDatabaseFullPagePresentation(fullPageDatabase);
  renderTopbarPageActions(State.pageData?.page || null);
  blocks.filter(block => block.type === 'tabs').forEach(normalizeTabsBlock);
  const outline = EditorCore.blockOutline(blocks), renderedRows = [];
  const numberedCounters = Array(33).fill(0);
  const canEdit = activePageCanEdit();
  blocks.forEach((block, index) => {
    const structure = outline[index], indent = structure.indent;
    const hiddenByToggle = structure.collapsed;
    const tabGroup = String(block.props?.tab_group || "");
    const hiddenByTab = structure.hiddenByTab;
    const row = document.createElement("div");
    row.className = "block-row" + (State.selectedBlockIds.has(block.id) ? " selected" : "")
      + (canEdit ? "" : " read-only");
    row.dataset.type = block.type || "paragraph";
    row.dataset.index = String(index);
    row.dataset.blockId = block.id || "";
    if (tabGroup) row.dataset.tabGroup = tabGroup;
    if (block.type === "numbered") {
      numberedCounters[indent] += 1;
      numberedCounters.fill(0, indent + 1);
      row.style.setProperty("--notion-list-number", `"${numberedCounters[indent]}."`);
    } else {
      numberedCounters.fill(0);
    }
    row.hidden = fullPageDatabase ? block.id !== fullPageDatabase.id : hiddenByToggle || hiddenByTab;
    row.classList.toggle("full-page-database-row", Boolean(fullPageDatabase && block.id === fullPageDatabase.id));
    row.id = block.id ? `block-${block.id}` : "";
    row.innerHTML = `
      <div class="block-controls">
        <button type="button" class="block-control" data-action="insert" title="아래에 블록 추가 (Alt+클릭: 위에 추가)" ${canEdit ? "" : "disabled"}>${iconSvg("plus")}</button>
        <button type="button" class="block-control block-handle" data-action="menu" title="블록 메뉴" ${canEdit ? "" : "disabled"}>${iconSvg("drag")}</button>
      </div>
      <div class="block-main">${blockEditorHtml(block, canEdit)}</div>
    `;
    applyBlockVisual(row, block);
    const editor = row.querySelector(".block-editor");
    if (editor) {
      editor.addEventListener("focus", () => {
        State.activeBlockId = block.id;
        clearBlockSelection();
      });
      editor.addEventListener("compositionstart", () => {
        editor.dataset.imeComposing = "true";
        EditorHost.beginComposition(block.id || "");
      });
      editor.addEventListener("compositionend", () => {
        const wasComposing = editor.dataset.imeComposing === "true";
        editor.dataset.imeComposing = "false";
        try {
          commitBlockEditorInput(editor, block, index, row);
        } finally {
          if (wasComposing) EditorHost.endComposition(block.id || "");
        }
      });
      editor.addEventListener("input", event => {
        if (event.isComposing || editor.dataset.imeComposing === "true") {
          syncEditorBlock(editor, block);
          syncSyncedBlockPeers(block, index);
          refreshBlockSlashMenu(editor, block, index, row, true);
          return;
        }
        commitBlockEditorInput(editor, block, index, row);
      });
      editor.addEventListener("keydown", event => handleBlockEditorKeydown(event, editor, block, index));
      editor.addEventListener("paste", event => handleBlockPaste(event, editor, block, index));
      editor.addEventListener("click", event => {
        const reminder = event.target.closest?.("span[data-notion-reminder]");
        if (reminder) {
          event.preventDefault();
          openInlineReminderDialog(reminder, editor, block);
          return;
        }
        const anchor = event.target.closest?.("a[href]");
        if (!anchor) return;
        try {
          const url = new URL(anchor.getAttribute("href"), location.origin);
          const match = url.origin === location.origin && url.pathname.match(/^\/page\/(.+)$/);
          if (!match) return;
          event.preventDefault();
          openPage(decodeURIComponent(match[1]));
        } catch {}
      });
    }
    const checkbox = row.querySelector(".todo-control input");
    if (checkbox) {
      checkbox.addEventListener("change", e => {
        block.props = block.props || {};
        block.props.checked = e.target.checked;
        markDirty();
      });
    }
    row.querySelector("[data-toggle-block]")?.addEventListener("click", () => {
      block.props = block.props || {};
      block.props.open = block.props.open === false;
      markDirty();
      renderBlocks();
    });
    if (block.type === "ai_notes") bindAiNotesBlock(row, block, false);
    if (block.type === "equation") bindEquationBlock(row, block, false);
    if (block.type === "embed" && block.props?.embed_mode === "html") bindHtmlEmbedBlock(row, block, false);
    attachBlockExtras(row, block, index, canEdit);
    row.querySelector('[data-action="insert"]').addEventListener("click", e => {
      if (e.detail === 0) insertSimpleBlockFromControl(index, e.altKey);
      else insertBlockFromControl(index, e.altKey, e.currentTarget);
    });
    row.querySelector('[data-action="menu"]').addEventListener("click", e => {
      if (e.shiftKey || !State.selectedBlockIds.has(block.id)) selectBlockHandle(index, e.shiftKey);
      openBlockMenu(index, e.currentTarget, "actions");
    });
    const isBlockSelectionClick = event => event.shiftKey && event.button === 0
      && !event.target.closest("input, textarea, select, a, button:not([data-action='menu'])")
      && (event.altKey || State.selectedBlockIds.size > 0);
    row.addEventListener("mousedown", event => {
      if (isBlockSelectionClick(event)) event.preventDefault();
    }, true);
    row.addEventListener("click", event => {
      if (!isBlockSelectionClick(event)) return;
      event.preventDefault();
      event.stopPropagation();
      document.activeElement?.blur?.();
      window.getSelection()?.removeAllRanges();
      if (event.altKey) toggleBlockSelectionAt(index);
      else selectBlockHandle(index, true);
    }, true);
    bindBlockDrag(row, block, index, canEdit);
    renderedRows.push(row);
  });
  const layout = window.NotionBlockLayout.mount({root, blocks, rows:renderedRows, outline,
    applyVisual:applyBlockVisual, fullPageId:fullPageDatabase?.id || ''});
  if (canEdit) {
    layout.columns.forEach(({element:column, groupId, columnCount, columnIndex, memberIds, parentIndex}) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "block-column-add";
        button.textContent = "＋";
        button.title = "이 열에 블록 추가";
        button.addEventListener("click", () => addBlockToColumn(groupId, columnIndex, columnCount, memberIds, blocks[parentIndex]?.id));
        column.appendChild(button);
    });
  }
  window.NotionPageOutline?.refresh();
  renderRemoteCursors();
  mountSyncedReferences(root);
  mountLinkedDatabases(root);
  root.querySelectorAll('.block-row[data-block-id] .dynamic-table-grid').forEach(scroll=>{
    if(scroll.closest('[data-linked-database]'))return;
    const blockId=scroll.closest('.block-row[data-block-id]')?.dataset.blockId;
    if(previousTableScroll.has(blockId))scroll.scrollLeft=previousTableScroll.get(blockId);
  });
  root.querySelectorAll('.block-row[data-block-id] .database-view-tabs').forEach(scroll=>{
    const blockId=scroll.closest('.block-row[data-block-id]')?.dataset.blockId;
    if(previousViewTabsScroll.has(blockId))scroll.scrollLeft=previousViewTabsScroll.get(blockId);
    revealDatabaseViewTab(scroll.querySelector('[aria-selected="true"]'));
  });
  root.querySelectorAll('.block-row[data-block-id] .timeline-block.hour-scale .timeline-scroll').forEach(scroll => {
    if(scroll.closest('[data-linked-database]'))return;
    const blockId = scroll.closest('.block-row[data-block-id]')?.dataset.blockId;
    const previous = previousHourScroll.get(blockId);
    const override=TimelineHourScrollRestores.get(blockId);
    TimelineHourScrollRestores.delete(blockId);
    const nowSlot = Number(scroll.dataset.timelineNowSlot);
    scroll.scrollLeft = override ?? previous ?? (scroll.hasAttribute('data-timeline-now-slot')
      && Number.isFinite(nowSlot) ? Math.max(0, nowSlot * 72 - scroll.clientWidth * .8) : 0);
    const block=blocks.find(item=>item.id===blockId);
    window.NotionTimelineHourWindow.bind(scroll,blockId,
      block?.props?.timeline_anchor||localIsoDate(new Date()),left=>{
        TimelineHourScrollRestores.set(blockId,left);
        renderBlocks();
      });
  });
  if (pendingLinkedDatePicker && !root.querySelector(`[data-linked-database="${CSS.escape(pendingLinkedDatePicker.blockId)}"]`))
    pendingLinkedDatePicker.dismiss();
  rebindBlockSlashMenu();
  rebindInsertedBlockMenu(root);
  renderPageInlineCommentMarkers();
  restoreDatabaseControlFocus(controlFocus);
  if(openTemplateBlockId){
    const restored=root.querySelector(`.block-row[data-block-id="${CSS.escape(openTemplateBlockId)}"]`);
    showDatabaseTemplatePicker(restored?.querySelector('[data-db-template-picker]'),
      restored?.querySelector('[data-db-template-popover]'),openTemplateFocus);
  }
  if(fileMenuHadUploadFocus && DatabaseFileAddMenu.toggle?.isConnected){
    const menu=DatabaseFileAddMenu.toggle.nextElementSibling;
    if(menu?.classList.contains('database-file-menu')&&!menu.hidden)
      menu.querySelector('.database-file-add')?.focus({preventScroll:true});
  }
  if (previousDateBlockId && !previousDateLinked && activeDatabaseDatePickerReanchor) {
    const blockRoot = [...root.querySelectorAll('.block-row[data-block-id]')]
      .find(row => row.dataset.blockId === previousDateBlockId);
    const nextAnchor = blockRoot && refreshedDatabaseDateButton(blockRoot, previousDateAnchor);
    const block = State.pageData.blocks.find(item => item.id === previousDateBlockId);
    const signature = block && databaseDateCellSignature(block, previousDateAnchor);
    if (nextAnchor && !nextAnchor.disabled && signature === activeDatabaseDatePickerSignature
        && nextAnchor.dataset.dbCellVersion === previousDateAnchor.dataset.dbCellVersion)
      activeDatabaseDatePickerReanchor(nextAnchor);
    else activeDatabaseDatePickerDismiss?.();
  }
}

function syncSyncedBlockPeers(source, sourceIndex) {
  if (source?.type !== "synced_block" || !source.props?.sync_id) return;
  if (window.NotionSyncedReferences.explicit(source)) return;
  State.pageData.blocks.forEach((block, index) => {
    if (index === sourceIndex || block.type !== "synced_block" || block.props?.sync_id !== source.props.sync_id) return;
    if (window.NotionSyncedReferences.explicit(block)) return;
    block.content = source.content;
    const indent = block.props?.indent;
    block.props = EditorCore.deepClone(source.props || {});
    if (indent != null) block.props.indent = indent;
    const peer = document.querySelector(`.block-row[data-index="${index}"] .block-editor`);
    if (peer && peer !== document.activeElement) peer.innerHTML = blockRichHtml(block);
  });
}

function handleBlockPaste(event, editor, block, index) {
  if (pasteSyncedReference(event, index)) return;
  if (!activePageCanEdit()) return;
  if (pasteStructuredBlocks(event, index)) return;
  const text = event.clipboardData?.getData("text/plain") || "";
  const html = event.clipboardData?.getData("text/html") || "";
  if (block.type === "equation") {
    event.preventDefault();
    document.execCommand("insertText", false, text);
    syncEditorBlock(editor, block);
    markDirty();
    return;
  }
  const selection = window.getSelection();
  if (selection && !selection.isCollapsed && /^(https?:\/\/|mailto:|tel:)/i.test(text.trim())) {
    event.preventDefault();
    document.execCommand("createLink", false, normalizeUrl(text.trim()));
    syncEditorBlock(editor, block);
    markDirty();
    return;
  }
  if (/\r?\n/.test(text)) {
    event.preventDefault();
    pasteMultilineAt(index, editor, text);
    return;
  }
  event.preventDefault();
  if (html) document.execCommand("insertHTML", false, sanitizeRichHtml(html));
  else document.execCommand("insertText", false, text);
  syncEditorBlock(editor, block);
  markDirty();
}

function openBlockPreview(block) {
  const type = block?.type || "";
  const fileId = String(block?.props?.file_id || "");
  const internalUrl = notionFileUrl(fileId);
  const externalUrl = safeExternalUrl(block?.props?.url || block?.props?.link_url || "");
  const url = internalUrl || externalUrl;
  if (!url) return false;
  const label = block?.props?.name || block?.content || blockTypeMeta(type)[1];
  let preview = "";
  if (type === "image") preview = `<img src="${escapeAttr(url)}" alt="${escapeAttr(label)}">`;
  else if (type === "video") preview = `<video src="${escapeAttr(url)}" controls autoplay></video>`;
  else if (type === "audio") preview = `<audio src="${escapeAttr(url)}" controls autoplay></audio>`;
  else if (type === "pdf") preview = `<iframe src="${escapeAttr(url)}" title="${escapeAttr(label)}"></iframe>`;
  else if (type === "embed") preview = `<iframe src="${escapeAttr(url)}" title="${escapeAttr(label)}" sandbox="allow-scripts allow-same-origin allow-popups" referrerpolicy="no-referrer"></iframe>`;
  else return false;
  openModal(label, `<div class="block-preview-modal">${preview}</div>`, [{ label: "닫기", action: closeModal }]);
  return true;
}

function modifyBlockAt(index) {
  const block = State.pageData?.blocks?.[index];
  if (!block) return false;
  if (block.type === "todo") {
    block.props = block.props || {};
    block.props.checked = !block.props.checked;
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(index, block.content.length);
    return true;
  }
  if (["toggle", "toggle_heading1", "toggle_heading2", "toggle_heading3", "toggle_heading4"].includes(block.type)) {
    block.props = block.props || {};
    block.props.open = block.props.open === false;
    markDirty();
    renderBlocks();
    focusBlock(index, block.content.length);
    return true;
  }
  if (block.type === "child_page" && block.props?.page_id) {
    openPage(block.props.page_id);
    return true;
  }
  if (block.type === "button") {
    runNotionButton(block, index);
    return true;
  }
  return openBlockPreview(block);
}

function toggleAllBlocks() {
  const toggles = (State.pageData?.blocks || []).filter(block => [
    "toggle", "toggle_heading1", "toggle_heading2", "toggle_heading3", "toggle_heading4",
  ].includes(block.type));
  if (!toggles.length) return false;
  const shouldOpen = toggles.some(block => block.props?.open === false);
  toggles.forEach(block => {
    block.props = block.props || {};
    block.props.open = shouldOpen;
  });
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
  setStatus(shouldOpen ? "모든 토글을 펼쳤습니다." : "모든 토글을 접었습니다.", "ok");
  return true;
}

function handleBlockEditorKeydown(event, editor, block, index) {
  if (!activePageCanEdit()) return;
  const key = event.key;
  const command = event.ctrlKey || event.metaKey;
  if (
    event.isComposing
    || editor.dataset?.imeComposing === "true"
    || event.keyCode === 229
  ) {
    finishComposingSlash(event, editor, block, index);
    return;
  }
  const slashMenuOpen = !$("#blockMenu").hidden && State.menuMode === "slash" && State.slashSourceIndex === index;
  const mentionMenuOpen = !$("#mentionMenu").hidden && State.mention.blockIndex === index;

  if (mentionMenuOpen && ["ArrowDown", "ArrowUp", "Enter"].includes(key)) {
    event.preventDefault();
    if (key === "ArrowDown") moveMentionSelection(1);
    else if (key === "ArrowUp") moveMentionSelection(-1);
    else mentionButtons()[State.mention.selectedIndex]?.click();
    return;
  }
  if (mentionMenuOpen && key === "Escape") {
    event.preventDefault();
    closeMentionMenu();
    return;
  }

  if (slashMenuOpen && ["ArrowDown", "ArrowUp", "Enter"].includes(key)) {
    event.preventDefault();
    if (key === "ArrowDown") moveBlockMenuSelection(1);
    else if (key === "ArrowUp") moveBlockMenuSelection(-1);
    else activateBlockMenuSelection();
    return;
  }
  if (slashMenuOpen && key === "Escape") {
    event.preventDefault();
    closeBlockMenu();
    return;
  }

  if (command && !event.shiftKey && key.toLowerCase() === "a") {
    const selectedText = selectionOffsets(editor);
    const textLength = editorPlainText(editor).length;
    const coversEditor = selectedText
      && Math.min(selectedText.start, selectedText.end) === 0
      && Math.max(selectedText.start, selectedText.end) === textLength;
    if (coversEditor) {
      event.preventDefault();
      event.stopPropagation();
      State.selectedBlockIds = new Set(
        (State.pageData?.blocks || []).map(candidate => candidate.id),
      );
      State.activeBlockId = block.id;
      document.querySelectorAll(".block-row").forEach(row => {
        row.classList.toggle("selected", State.selectedBlockIds.has(row.dataset.blockId));
      });
      window.getSelection()?.removeAllRanges();
      $("#pageEditorGroup")?.focus({preventScroll:true});
      return;
    }
  }

  if (command && key.toLowerCase() === "s") {
    event.preventDefault();
    syncEditorBlock(editor, block);
    captureEditorHistory(true);
    savePage();
    return;
  }
  if (command && key.toLowerCase() === "p") {
    event.preventDefault();
    openSearchOverlay();
    return;
  }
  if (command && key.toLowerCase() === "z") {
    event.preventDefault();
    applyEditorHistory(event.shiftKey ? 1 : -1, {
      blockIndex: index,
      offset: caretOffset(editor),
    });
    return;
  }
  if (command && key.toLowerCase() === "y") {
    event.preventDefault();
    applyEditorHistory(1, {
      blockIndex: index,
      offset: caretOffset(editor),
    });
    return;
  }
  if (command && !event.shiftKey && ["b", "i", "u", "e"].includes(key.toLowerCase())) {
    event.preventDefault();
    const format = { b: "bold", i: "italic", u: "underline" }[key.toLowerCase()];
    if (key.toLowerCase() === "e") toggleInlineCode();
    else applyInlineFormat(format);
    syncEditorBlock(editor, block);
    return;
  }
  if (command && event.shiftKey && key.toLowerCase() === "s") {
    event.preventDefault();
    applyInlineFormat("strikeThrough");
    syncEditorBlock(editor, block);
    return;
  }
  if (command && !event.shiftKey && key.toLowerCase() === "k") {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) {
      event.preventDefault();
      event.stopPropagation();
      openSearchOverlay();
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    updateInlineToolbar();
    openInlineLinkPopover();
    return;
  }
  if (command && key === "/") {
    event.preventDefault();
    syncEditorBlock(editor, block);
    const anchor = editor.closest(".block-row")?.querySelector('[data-action="menu"]') || editor;
    selectBlockHandle(index);
    openBlockMenu(index, anchor, "actions");
    return;
  }
  if (command && key === "Enter") {
    event.preventDefault();
    syncEditorBlock(editor, block);
    if (block.type === "equation") {
      markDirty();
      editor.blur();
      return;
    }
    modifyBlockAt(index);
    return;
  }
  if (block.type === "equation" && key === "Enter") return;
  if (command && event.altKey && key.toLowerCase() === "t") {
    event.preventDefault();
    toggleAllBlocks();
    return;
  }
  if (command && event.shiftKey && key.toLowerCase() === "h") {
    const offset = caretOffset(editor);
    if (applyLastBlockColor(index)) {
      event.preventDefault();
      focusBlock(index, Math.min(block.content.length, offset));
    }
    return;
  }
  if (command && !event.shiftKey && key.toLowerCase() === "d") {
    event.preventDefault();
    const indices = selectedBlockIndices(index);
    if (!databaseStructureMutationAllowed(indices)) return;
    if (!duplicateSelectedEditorBlocks(indices)) return;
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(index + 1, 0);
    return;
  }
  if (command && event.shiftKey && (key === "ArrowUp" || key === "ArrowDown")) {
    event.preventDefault();
    const offset = caretOffset(editor);
    const target = key === "ArrowUp" ? index - 1 : index + 1;
    try { State.pageData.blocks = EditorCore.moveBlock(State.pageData.blocks, index, target); }
    catch (error) {setStatus(error.message,'error');return;}
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(State.pageData.blocks.findIndex(item=>item.id===block.id), offset);
    return;
  }
  if (command && event.shiftKey && key.toLowerCase() === "m") {
    event.preventDefault();
    const selection = window.getSelection();
    openSelectedCommentComposer(editor, block.id, selection?.rangeCount ? selection.getRangeAt(0) : null);
    return;
  }
  const shortcutDigit = /^[0-9]$/.test(key) ? key : (/^Digit[0-9]$/.test(event.code || "") ? event.code.slice(-1) : "");
  if (command && event.shiftKey && shortcutDigit) {
    const mapping = {
      "0": "paragraph", "1": "heading1", "2": "heading2", "3": "heading3", "4": "todo",
      "5": "bullet", "6": "numbered", "7": "toggle", "8": "code", "9": "child_page",
    };
    if (mapping[shortcutDigit]) {
      event.preventDefault();
      if (mapping[shortcutDigit] === "child_page") insertChildPageAfter(index, true);
      else changeBlockType(index, mapping[shortcutDigit]);
      return;
    }
  }
  if (event.altKey && event.shiftKey && key.toLowerCase() === "l") {
    event.preventDefault();
    copyText(`${pageUrl(State.activePageId)}#block-${block.id || index}`, "블록 링크 복사됨");
    return;
  }
  if (key === "Escape") {
    event.preventDefault();
    syncEditorBlock(editor, block);
    if (EmbeddedEditorFrame) { void window.NotionEmbeddedEditor?.close(); return; }
    editor.blur();
    selectBlockHandle(index);
    return;
  }
  if (key === "Tab") {
    event.preventDefault();
    if (block.type === "code") {
      document.execCommand("insertText", false, event.shiftKey ? "" : "\t");
      syncEditorBlock(editor, block);
      markDirty();
      return;
    }
    const offset = caretOffset(editor);
    try { State.pageData.blocks = window.NotionBlockStructure.indent(State.pageData.blocks,[index],event.shiftKey ? -1 : 1); }
    catch (error) {setStatus(error.message,'error');return;}
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(State.pageData.blocks.findIndex(item=>item.id===block.id), offset);
    return;
  }
  if (key === "Enter" && event.shiftKey) {
    event.preventDefault();
    insertSoftBreak(editor, block);
    return;
  }
  if (key === "Enter" && !event.shiftKey) {
    if (block.type === "code" && !command) {
      event.preventDefault();
      insertSoftBreak(editor, block);
      return;
    }
    event.preventDefault();
    syncEditorBlock(editor, block);
    if (!block.content && EditorCore.LIST_BLOCK_TYPES.has(block.type)) {
      const layout = block.props?.layout_group ? {
        layout_group: block.props.layout_group,
        layout_column: Number(block.props.layout_column || 0),
        layout_columns: Number(block.props.layout_columns || 2),
      } : {};
      block.type = "paragraph";
      block.props = layout;
      markDirty();
      captureEditorHistory(true);
      renderBlocks();
      focusBlock(index, 0);
      return;
    }
    const offset = caretOffset(editor);
    const [first, second] = EditorCore.splitBlock(block, offset);
    EditorCore.replaceBlockRange(State.pageData.blocks, index, 1, first, second);
    markDirty();
    captureEditorHistory(true);
    renderBlocks();
    focusBlock(index + 1, 0);
    return;
  }
  if (key === "Backspace" && selectionIsCollapsed(editor) && caretOffset(editor) === 0) {
    if (index === 0 && !command && !event.altKey && !event.shiftKey && mergeFirstParagraphIntoTitle(editor, block, index)) {
      event.preventDefault();
      return;
    }
    if (!block.content && block.type !== "paragraph") {
      event.preventDefault();
      const layout = block.props?.layout_group ? {
        layout_group: block.props.layout_group,
        layout_column: Number(block.props.layout_column || 0),
        layout_columns: Number(block.props.layout_columns || 2),
      } : {};
      block.type = "paragraph";
      block.props = layout;
      markDirty();
      captureEditorHistory(true);
      renderBlocks();
      focusBlock(index, 0);
      return;
    }
    if (index > 0 && EditorCore.isTextBlock(State.pageData.blocks[index - 1].type)) {
      const structure = EditorCore.blockOutline(State.pageData.blocks);
      if (structure[index].scope !== structure[index - 1].scope || structure[index].parentIndex !== structure[index - 1].parentIndex || structure[index].childIndices.length) return;
      event.preventDefault();
      if (window.NotionSyncedReferences.reference(State.pageData.blocks[index - 1])) {
        selectBlockHandle(index - 1);
        editor.blur();
        return;
      }
      syncEditorBlock(editor, block);
      const merged = EditorCore.mergeBlocks(State.pageData.blocks[index - 1], block);
      EditorCore.replaceBlockRange(State.pageData.blocks, index - 1, 2, merged.block);
      markDirty();
      captureEditorHistory(true);
      renderBlocks();
      focusBlock(index - 1, merged.caret);
    }
  }
  if (key === "Delete" && selectionIsCollapsed(editor) && caretOffset(editor) === editorPlainText(editor).length) {
    const next = State.pageData.blocks[index + 1];
    if (next && EditorCore.isTextBlock(next.type)) {
      const structure = EditorCore.blockOutline(State.pageData.blocks);
      if (structure[index].scope !== structure[index + 1].scope || structure[index].parentIndex !== structure[index + 1].parentIndex || structure[index + 1].childIndices.length) return;
      event.preventDefault();
      if (window.NotionSyncedReferences.reference(next)) {
        selectBlockHandle(index + 1);
        editor.blur();
        return;
      }
      syncEditorBlock(editor, block);
      const merged = EditorCore.mergeBlocks(block, next);
      EditorCore.replaceBlockRange(State.pageData.blocks, index, 2, merged.block);
      markDirty();
      captureEditorHistory(true);
      renderBlocks();
      focusBlock(index, merged.caret);
    }
  }
}

function linkPreviewHtml(block, index, canEdit) {
  const url = normalizeUrl(block.props?.link_url || "");
  if (!url) return "";
  return `
    <div class="link-preview" data-link-index="${index}">
      <span>⌁</span>
      <a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(url)}</a>
      <button type="button" data-link-copy="${index}" title="링크 복사">⧉</button>
      ${canEdit ? `<button type="button" data-link-edit="${index}" title="편집">편집</button>` : ""}
    </div>
  `;
}

function mediaToolbarHtml(index, url, type, canEdit) {
  if (!url) return "";
  return `
    <div class="media-toolbar">
      <button type="button" data-media-comment="${index}" title="댓글">☰</button>
      <button type="button" data-media-caption="${index}" title="캡션">▤</button>
      <button type="button" data-action-plus="${index}" title="아래에 블록 추가" ${canEdit ? "" : "disabled"}>＋</button>
      <a href="${url}" target="_blank" title="확대">⌕</a>
      <a href="${url}" download title="다운로드">↓</a>
      <button type="button" data-media-more="${index}" title="더보기">…</button>
    </div>
  `;
}

function richTextEditorHtml(block, canEdit, placeholder = "입력하세요. '/'로 블록을 선택할 수 있습니다.") {
  return `<div class="block-editor" role="textbox" aria-label="페이지 블록" aria-multiline="true" aria-readonly="${canEdit ? "false" : "true"}" contenteditable="${canEdit ? "true" : "false"}" spellcheck="true" data-placeholder="${escapeAttr(placeholder)}">${blockRichHtml(block)}</div>`;
}

function safeExternalUrl(value) {
  const url = normalizeUrl(value || "");
  return /^https?:\/\//i.test(url) ? url : "";
}

function tableOfContentsHtml() {
  const headings = (State.pageData?.blocks || []).filter(block => [
    "heading1", "heading2", "heading3", "heading4", "toggle_heading1", "toggle_heading2", "toggle_heading3", "toggle_heading4",
  ].includes(block.type) && block.content);
  if (!headings.length) return '<div class="toc-empty">제목 블록을 추가하면 목차가 표시됩니다.</div>';
  return `<nav class="table-of-contents">${headings.map(block => {
    const level = Number(block.type.slice(-1)) || 1;
    return `<a href="#block-${escapeAttr(block.id || "")}" style="--toc-level:${level}">${escapeHtml(block.content)}</a>`;
  }).join("")}</nav>`;
}

function breadcrumbBlockHtml() {
  const crumbs = pageCrumbs(State.pageData?.page || {});
  return `<nav class="breadcrumb-block">${crumbs.map((page, index) => `
    <button type="button" data-breadcrumb-page="${escapeAttr(page.id || "")}">${escapeHtml(page.title || "제목 없음")}</button>
    ${index < crumbs.length - 1 ? "<span>/</span>" : ""}
  `).join("")}</nav>`;
}

function sidePeekIconHtml() {
  return '<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true" focusable="false"><rect x="2" y="3" width="16" height="14" rx="2"/><path d="M12 3v14M5 10h5m-2-2 2 2-2 2"/></svg>';
}

function syncPageTitleDisplays(pageId, title) {
  const page = State.pages.find(item => item.id === pageId);
  if (!page) return;
  page.title = String(title ?? "");
  document.querySelectorAll(".page-row[data-page-id]").forEach(row => {
    if (row.dataset.pageId !== pageId) return;
    const label = row.querySelector(".page-title-label");
    if (label && label.textContent !== (page.title || "제목 없음")) label.textContent = page.title || "제목 없음";
    if (label) label.title = page.title || "제목 없음";
    row.setAttribute("aria-label", page.title || "제목 없음");
    const icon = row.querySelector(".page-icon");
    if (icon) {
      const html = pageIconHtml(page);
      if (icon.innerHTML !== html) icon.innerHTML = html;
      if (icon.matches("button")) icon.setAttribute("aria-label", `${page.title || "제목 없음"} 아이콘 변경`);
    }
  });
  refreshPageReferenceDisplays();
}

function pageMetadataScope() {
  return State.navigation.collaborativeSharing && State.user?.id && State.navigation.workspaceId
    ? {subject_id: State.user.id, workspace_id: State.navigation.workspaceId} : null;
}

let PageMetadataReadSequence = 0;
let PageNavigationReadSequence = 0;
async function refreshPageNavigation(scopeKey) {
  const request = ++PageNavigationReadSequence;
  const sequence = State.navigation.sequence, workspaceId = State.navigation.workspaceId;
  const query = $("#pageSearch")?.value || "";
  const items = await fetchWorkspacePagesSnapshot(workspaceId, query, sequence);
  if (!items || request !== PageNavigationReadSequence || sequence !== State.navigation.sequence
      || window.NotionMetadataSync.scopeKey(pageMetadataScope()) !== scopeKey
      || query !== ($("#pageSearch")?.value || "")) return;
  // Navigation invalidations never replace an open editor, its draft or IME.
  applyWorkspacePagesSnapshot(items, {preserveActivePage: true});
  if (query && document.querySelector("[data-page-reference], [data-database-page-icon]")) {
    try {
      const references = await fetchWorkspacePagesSnapshot(workspaceId, "", sequence);
      if (references && request === PageNavigationReadSequence && sequence === State.navigation.sequence
          && window.NotionMetadataSync.scopeKey(pageMetadataScope()) === scopeKey
          && query === ($("#pageSearch")?.value || "")) refreshPageReferenceDisplays(references);
    } catch (_) { /* Keep current link displays until the next scoped read. */ }
  }
}

let PageMetadataPendingScope = "";
const PageMetadataPendingReads = new Set();

async function refreshVisiblePageMetadata(ids, scopeKey) {
  if (PageMetadataPendingScope !== scopeKey) PageMetadataPendingReads.clear();
  PageMetadataPendingScope = scopeKey;
  ids.forEach(id => PageMetadataPendingReads.add(id));
  const requestedIds = [...PageMetadataPendingReads];
  const request = ++PageMetadataReadSequence;
  const sequence = State.navigation.sequence, workspaceId = State.navigation.workspaceId;
  const items = await fetchWorkspacePagesSnapshot(workspaceId, "", sequence);
  if (!items || request !== PageMetadataReadSequence || sequence !== State.navigation.sequence
      || window.NotionMetadataSync.scopeKey(pageMetadataScope()) !== scopeKey) return;
  PageMetadataPendingReads.clear();
  const current = new Map(items.map(item => [item.id, item]));
  let hierarchyChanged = false;
  for (const id of requestedIds) {
    const listed = State.pages.find(item => item.id === id), fresh = current.get(id);
    if (!fresh) {
      hierarchyChanged ||= Boolean(listed);
      State.pages = State.pages.filter(item => item.id !== id);
      document.querySelectorAll(".page-row[data-page-id]").forEach(row => { if (row.dataset.pageId === id) row.remove(); });
      if (State.activePageId === id) {
        State.liveCollaboration.accessRecoveryPending = true;
        enterCollaborativeRecoveryOnly("페이지 접근 권한을 다시 확인해 주세요. 작성 중인 입력은 유지됩니다.");
      }
      if (State.sidePeek.pageId === id && State.sidePeek.routeVisible && !State.sidePeek.archived) {
        void showArchivedSidePeekIfAuthorized(id, State.sidePeek).catch(() => {});
      }
      continue;
    }
    const knownPages = [listed, State.pageData?.page, State.sidePeek.data?.page].filter(page => page?.id === id);
    const knownSequence = Math.max(0, ...knownPages.flatMap(page => [Number(page.document_sequence || 0), Number(page.activity_document_sequence || 0)]));
    if (Number(fresh.document_sequence || 0) < knownSequence) continue;
    const activePage = State.activePageId === id ? State.pageData?.page : null;
    const wasLocked = activePage?.id === id ? pageIsLocked(activePage) : null;
    const priorSettings = activePage?.id === id ? JSON.stringify(activePage.settings || {}) : null;
    const priorCanEdit = activePage?.id === id ? Boolean(activePage.can_edit) : null;
    const priorIamRole = activePage?.id === id ? String(activePage.iam_role || '') : null;
    hierarchyChanged ||= Boolean(listed && (listed.parent_id !== fresh.parent_id || listed.position !== fresh.position || listed.can_move !== fresh.can_move || listed.can_edit !== fresh.can_edit));
    if (listed) Object.assign(listed, fresh);
    if (listed && "updated_at" in fresh) listed.activity_document_sequence = Number(fresh.document_sequence || 0);
    for (const data of [State.pageData, State.sidePeek.data]) {
      if (data?.page?.id !== id) continue;
      for (const key of ["parent_id", "can_edit", "can_share", "can_move", "can_change_settings", "can_change_appearance", "settings", "lock_generation", "iam_role", "role", "workspace_epoch", "document_epoch", "updated_at"]) {
        if (key in fresh) data.page[key] = fresh[key];
      }
      if ("updated_at" in fresh) data.page.activity_document_sequence = Number(fresh.document_sequence || 0);
    }
    closeIconPickerAfterAccessChange(id);
    const grantRevoked = reconcileTemporaryUnlockGrant(activePage?.id === id ? activePage : listed);
    if (grantRevoked) hierarchyChanged = true;
    const accessChanged = activePage?.id === id && (priorCanEdit !== Boolean(activePage.can_edit)
      || priorIamRole !== String(activePage.iam_role || ''));
    if (activePage?.id === id && (wasLocked !== pageIsLocked(activePage)
        || priorSettings !== JSON.stringify(activePage.settings || {}) || accessChanged)) {
      refreshPageSettingsControls(id, wasLocked !== pageIsLocked(activePage) || accessChanged);
      renderTopbarPageActions(activePage);
      refreshOpenPageMenu(activePage);
      if (accessChanged) {
        syncPageShareControls();
        renderComments();
      }
    }
    // A list refresh must not replace unacknowledged text or an IME composition.
    const editingTitle = State.activePageId === id && State.pageData?.page?.collaborative_editing === true
      && State.liveCollaboration.crdtReady ? State.pageData.page.title : fresh.title;
    syncPageTitleDisplays(id, editingTitle);
    const live = State.liveCollaboration;
    if (activePage?.id === id && live.accessRecoveryPending && live.recoveryOnly) {
      const unsent = live.unsyncedCount > 0 || live.pendingEnvelopes.size > 0;
      if (!unsent && !live.offlinePolicyBlocked && !State.dirty) {
        live.accessRecoveryPending = false;
        void startLiveCollaboration().catch(error => {
          setStatus(`페이지 협업 복구 실패: ${error.message}`, "error");
        });
      } else if (unsent || State.dirty) {
        const reason = unsent
          ? "접근 권한은 다시 확인됐지만 이전 권한 상태의 미전송 편집은 자동 저장하지 않습니다. 로컬 편집을 내보낸 뒤 페이지를 새로 열어 주세요."
          : "접근 권한은 다시 확인됐지만 저장되지 않은 본문이 있어 자동 재연결하지 않았습니다. 작성 내용을 복사한 뒤 페이지를 새로 열어 주세요.";
        if (live.recoveryReason !== reason) {
          live.recoveryReason = reason;
          showCollaborativeRecoveryBanner(reason);
          setStatus(reason, "error");
        }
      }
    }
  }
  if (hierarchyChanged) renderPageLists();
  refreshPageReferenceDisplays(items.map(page =>
    page.id === State.activePageId && State.pageData?.page?.collaborative_editing
      && State.liveCollaboration.crdtReady
      ? {...page, title: State.pageData.page.title} : page));
  renderBreadcrumb(State.pageData?.page || null);
  renderPageActivity(State.pageData?.page || null);
}

async function refreshVisiblePageActivity(ids, scopeKey) {
  const navigation = State.navigation.sequence, workspaceId = State.navigation.workspaceId;
  await Promise.allSettled(ids.map(async id => {
    const data = await api(`/api/notion/workspaces/${encodeURIComponent(workspaceId)}/pages/${encodeURIComponent(id)}/activity`);
    if (navigation !== State.navigation.sequence || window.NotionMetadataSync.scopeKey(pageMetadataScope()) !== scopeKey) return;
    const fresh = data.page;
    if (fresh?.id !== id || fresh.workspace_id !== workspaceId || !Number.isSafeInteger(fresh.document_sequence)
        || fresh.document_sequence < 1 || !Number.isSafeInteger(fresh.updated_at) || fresh.updated_at < 0) return;
    const menu = $('#pageMenu');
    const menuPage = menu && !menu.hidden && menu.dataset.pageId === id
      && menu.pageMenuSubject === State.user?.id && menu.pageMenuWorkspace === workspaceId ? menu.pageMenuPage : null;
    const pages = [State.pages.find(page => page.id === id), State.pageData?.page, State.sidePeek.data?.page, menuPage]
      .filter(page => page?.id === id);
    for (const page of pages) {
      if (fresh.document_sequence < Math.max(Number(page.document_sequence || 0), Number(page.activity_document_sequence || 0))
          || Number(fresh.workspace_epoch || 0) < Number(page.workspace_epoch || 0)
          || Number(fresh.document_epoch || 0) < Number(page.document_epoch || 0)) continue;
      // This response covers activity only, not the body/DB snapshot or its CAS version.
      page.updated_at = fresh.updated_at;
      page.activity_document_sequence = fresh.document_sequence;
      window.NotionPageActivity?.apply(page, fresh);
    }
    const foot = menuPage && menu.querySelector('.menu-foot');
    if (foot && window.NotionPageActivity) {
      const activity = window.NotionPageActivity.footer(menuPage, [State.user, ...(State.users || [])], formatTime);
      foot.innerHTML = pageMenuFooter(menuPage, activity, menu.dataset.surface);
    }
    renderPageActivity(State.pageData?.page || null);
  }));
}

function installPageMetadataSync() {
  if (PageMetadataSync || !window.NotionMetadataSync) return;
  let channel = null;
  try { if (window.BroadcastChannel) channel = new window.BroadcastChannel("notion-page-metadata-v1"); } catch {}
  PageMetadataSync = window.NotionMetadataSync.create({
    channel, scope: pageMetadataScope, hasPage: id => State.pages.some(page => page.id === id)
      || State.pageData?.page?.id === id || State.sidePeek.data?.page?.id === id,
    refresh: refreshVisiblePageMetadata,
    refreshActivity: refreshVisiblePageActivity,
    refreshNavigation: refreshPageNavigation,
    setTimeout: (callback, delay) => window.setTimeout(callback, delay),
    clearTimeout: timer => window.clearTimeout(timer),
  });
  const refresh = () => {
    if (document.visibilityState === "visible") {
      const active = State.pageData?.page;
      const activeId = active?.id === State.activePageId && active.workspace_id === State.navigation.workspaceId
        ? active.id : "";
      PageMetadataSync.refresh([...State.pages.map(page => page.id), activeId].filter(Boolean));
      PageMetadataSync.refreshNavigation();
    }
  };
  window.addEventListener("focus", refresh);
  document.addEventListener("visibilitychange", refresh);
}

function pageReferenceMetadata(pageId, fallback, pages = pageReferenceDisplayPages()) {
  const page = pages.find(item => item.id === pageId);
  return {icon: page?.icon ?? "", title: page ? page.title || "제목 없음" : fallback || "제목 없음"};
}

function pageReferenceContentHtml(pageId, fallback, pages = pageReferenceDisplayPages()) {
  const page = pageReferenceMetadata(pageId, fallback, pages);
  return `${pageIconHtml(page)}<span>${escapeHtml(page.title)}</span>`;
}

function pageReferenceDisplayScope() {
  return JSON.stringify([State.user?.id || "", State.navigation?.enabled
    ? State.navigation.workspaceId || "" : "", State.navigation?.sequence || 0]);
}

function pageReferenceDisplayPages() {
  const snapshot = State.pageReferenceDisplay;
  if (snapshot && snapshot.scope !== pageReferenceDisplayScope()) {
    State.pageReferenceDisplay = null;
    return State.pages;
  }
  if (!$("#pageSearch")?.value || !snapshot) return State.pages;
  const listed = new Set(State.pages.map(page => page.id));
  return [...State.pages, ...snapshot.pages.filter(page => !listed.has(page.id))];
}

function refreshPageReferenceDisplays(referencePages = null) {
  // Only non-editable link contents change; keep their button, handlers, focus,
  // neighboring text nodes and the editor's body model intact.
  const filtered = referencePages === null && Boolean($("#pageSearch")?.value);
  const pages = referencePages || pageReferenceDisplayPages();
  if (!filtered) {
    // A complete authorized read replaces this display-only snapshot, including
    // removals. Scope changes make it unusable before any subsequent redraw.
    State.pageReferenceDisplay = {scope: pageReferenceDisplayScope(), pages: pages.map(page => ({
      id: page.id, title: page.title, icon: page.icon ?? "",
    }))};
  }
  document.querySelectorAll("[data-page-reference]").forEach(button => {
    const pageId = button.dataset.pageReference, fallback = button.dataset.pageReferenceFallback;
    if (filtered && !pages.some(item => item.id === pageId)) return;
    const html = pageReferenceContentHtml(pageId, fallback, pages);
    if (button.innerHTML !== html) button.innerHTML = html;
    const side = button.parentElement.querySelector("[data-child-page-side]");
    if (side?.dataset.childPageSide === pageId) {
      side.setAttribute("aria-label", `${pageReferenceMetadata(pageId, fallback, pages).title} 사이드 보기로 열기`);
    }
  });
  document.querySelectorAll("[data-database-page-icon]").forEach(element => {
    const pageId = element.dataset.databasePageIcon;
    const page = pages.find(item => item.id === pageId);
    // A filtered list omits accessible pages too; absence there is not a new
    // icon value. A complete list can clear a reference that is no longer read.
    if (!page && filtered) return;
    const html = pageIconHtml(page?.icon ?? element.dataset.databaseIconFallback ?? "");
    if (element.innerHTML !== html) element.innerHTML = html;
  });
}

function linkToPageBlockHtml(block, canEdit) {
  const pageId = String(block.props?.page_id || "");
  const linked = pageReferenceDisplayPages().find(page => page.id === pageId);
  if (linked) {
    return `<div class="child-page-row linked-page-row"><button type="button" class="linked-page-block" data-linked-page-open="${escapeAttr(linked.id)}" data-page-reference="${escapeAttr(linked.id)}">${pageReferenceContentHtml(linked.id)}</button>
      <button type="button" class="child-page-side" data-child-page-side="${escapeAttr(linked.id)}" aria-label="${escapeAttr(linked.title || "제목 없음")} 사이드 보기로 열기" title="사이드 보기로 열기 (Alt+클릭)">${sidePeekIconHtml()}<span>열기</span></button></div>
      ${canEdit ? `<select class="linked-page-select" data-linked-page-select><option value="">페이지 변경...</option>${visiblePages().filter(page => page.id !== State.activePageId).map(page => `<option value="${escapeAttr(page.id)}">${escapeHtml(page.title || "제목 없음")}</option>`).join("")}</select>` : ""}`;
  }
  return canEdit
    ? `<select class="linked-page-select" data-linked-page-select><option value="">연결할 페이지 선택</option>${visiblePages().filter(page => page.id !== State.activePageId).map(page => `<option value="${escapeAttr(page.id)}">${escapeHtml(page.title || "제목 없음")}</option>`).join("")}</select>`
    : '<span class="muted-block">연결된 페이지 없음</span>';
}

function simpleTableBlockHtml(block, canEdit) {
  block.props = block.props || {};
  let rows = Array.isArray(block.props.rows) ? block.props.rows.filter(row => Array.isArray(row)) : [];
  if (!rows.length) rows = [["", ""], ["", ""]];
  const columnCount = Math.max(1, ...rows.map(row => row.length));
  rows = rows.map(row => Array.from({ length: columnCount }, (_, index) => String(row[index] || "")));
  block.props.rows = rows;
  return `<div class="simple-table-wrap">
    <div class="simple-table" style="--simple-columns:${columnCount}">${rows.map((row, rowIndex) => row.map((value, columnIndex) => `
      <span data-grid-row="${rowIndex}" data-grid-column="${columnIndex}"><input aria-label="${rowIndex + 1}행 ${columnIndex + 1}열" class="${(block.props.header_row && rowIndex === 0) || (block.props.header_column && columnIndex === 0) ? "table-header-cell" : ""}" data-simple-cell data-row="${rowIndex}" data-column="${columnIndex}" value="${escapeAttr(value)}" ${canEdit ? "" : "disabled"}></span>
    `).join("")).join("")}</div>
    ${canEdit ? `<div class="simple-table-actions"><button type="button" data-simple-add-row>＋ 행</button><button type="button" data-simple-add-column>＋ 열</button><label><input type="checkbox" data-simple-header-row ${block.props.header_row ? "checked" : ""}> 머리글 행</label><label><input type="checkbox" data-simple-header-column ${block.props.header_column ? "checked" : ""}> 머리글 열</label></div>` : ""}
  </div>`;
}

function buttonBlockHtml(block, index, canEdit) {
  const props = block.props || {};
  const action = ["insert_block", "new_page", "open_url"].includes(props.action) ? props.action : "insert_block";
  const label = props.label || block.content || "버튼";
  return `<div class="notion-button-block">
    <button type="button" class="notion-action-button" data-run-button="${index}" ${!canEdit && action !== "open_url" ? "disabled" : ""}>⚡ ${escapeHtml(label)}</button>
    ${canEdit ? `<details><summary>버튼 설정</summary><div class="button-config">
      <input data-button-label value="${escapeAttr(label)}" placeholder="버튼 이름">
      <select data-button-action><option value="insert_block" ${action === "insert_block" ? "selected" : ""}>아래에 블록 삽입</option><option value="new_page" ${action === "new_page" ? "selected" : ""}>하위 페이지 만들기</option><option value="open_url" ${action === "open_url" ? "selected" : ""}>URL 열기</option></select>
      <input data-button-url value="${escapeAttr(props.url || "")}" placeholder="https://" ${action === "open_url" ? "" : "hidden"}>
    </div></details>` : ""}
  </div>`;
}

function newTabId() {
  return `tab_${crypto?.randomUUID?.().replace(/-/g, "") || Date.now().toString(36) + Math.random().toString(36).slice(2)}`;
}

function normalizeTabsBlock(block) {
  block.props = block.props && typeof block.props === "object" ? block.props : {};
  const seen = new Set();
  let tabs = Array.isArray(block.props.tabs) ? block.props.tabs : [];
  tabs = tabs.filter(item => item && item.id && !seen.has(String(item.id)) && seen.add(String(item.id))).slice(0, 20).map((item, index) => ({
    id: String(item.id).slice(0, 100),
    name: String(item.name || `탭 ${index + 1}`).slice(0, 100),
  }));
  while (tabs.length < 2) tabs.push({ id: newTabId(), name: `탭 ${tabs.length + 1}` });
  block.props.tabs = tabs;
  if (!tabs.some(item => item.id === block.props.active_tab_id)) block.props.active_tab_id = tabs[0].id;
  return tabs;
}

function tabsBlockHtml(block, canEdit) {
  const tabs = normalizeTabsBlock(block);
  return `<div class="notion-tabs-block" role="tablist" aria-label="페이지 탭">
    ${tabs.map(item => `<span class="notion-tab-chip${item.id === block.props.active_tab_id ? " active" : ""}">
      <button type="button" role="tab" aria-selected="${item.id === block.props.active_tab_id}" data-tab-select="${escapeAttr(item.id)}">${escapeHtml(item.name)}</button>
      ${canEdit ? `<button type="button" class="notion-tab-menu" data-tab-menu="${escapeAttr(item.id)}" title="탭 설정">•••</button>` : ""}
    </span>`).join("")}
    ${canEdit && tabs.length < 20 ? '<button type="button" class="notion-tab-add" data-tab-add title="탭 추가">＋</button>' : ""}
  </div>`;
}

function selectTabsBlockTab(block, tabId) {
  const tabs = normalizeTabsBlock(block);
  if (!tabs.some(item => item.id === tabId)) return;
  block.props.active_tab_id = tabId;
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
}

function addTabsBlockTab(block, blockIndex) {
  if (!activePageCanEdit()) return;
  blockIndex=State.pageData.blocks.findIndex(item=>item.id===block.id&&item.type==='tabs');
  if(blockIndex<0)return;
  const current=EditorCore.deepClone(State.pageData.blocks[blockIndex]);
  const tabs = normalizeTabsBlock(current);
  if (tabs.length >= 20) return;
  const tab = { id: newTabId(), name: `탭 ${tabs.length + 1}` };
  const member = EditorCore.createBlock("paragraph");
  try{State.pageData.blocks=window.NotionBlockStructure.appendTab(State.pageData.blocks.map((item,i)=>i===blockIndex?current:item),blockIndex,tab,member);}
  catch(error){setStatus(error.message,'error');return;}
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
  focusBlock(State.pageData.blocks.findIndex(item=>item.id===member.id), 0);
}

function deleteTabsBlockTab(block, tabId) {
  if(!activePageCanEdit())return;
  const index=State.pageData.blocks.findIndex(item=>item.id===block.id&&item.type==='tabs');
  if(index<0)return;
  const current=EditorCore.deepClone(State.pageData.blocks[index]);
  const tabs = normalizeTabsBlock(current);
  if (tabs.length <= 2 || !tabs.some(item => item.id === tabId)) return;
  if (!window.confirm("이 탭과 탭 안의 블록을 삭제할까요?")) return;
  try{State.pageData.blocks=window.NotionBlockStructure.removeTab(State.pageData.blocks.map((item,i)=>i===index?current:item),index,tabId);}
  catch(error){setStatus(error.message,'error');return;}
  closeModal();
  markDirty();
  captureEditorHistory(true);
  renderBlocks();
}

function openTabsBlockTabSettings(block, tabId) {
  if(!activePageCanEdit())return;
  const scope={pageId:State.activePageId,userId:State.user?.id,workspaceId:State.navigation?.workspaceId};
  const current=()=>scope.pageId===State.activePageId&&scope.userId===State.user?.id&&scope.workspaceId===State.navigation?.workspaceId&&activePageCanEdit()
    ?State.pageData.blocks.find(item=>item.id===block.id&&item.type==='tabs'):null;
  const controller=current();if(!controller)return;
  const tabs = normalizeTabsBlock(EditorCore.deepClone(controller));
  const tab = tabs.find(item => item.id === tabId);
  if (!tab) return;
  openModal("탭 설정", `<label class="database-rule-form">탭 이름<input id="tabNameInput" value="${escapeAttr(tab.name)}" maxlength="100"></label>`, [
    ...(tabs.length > 2 ? [{ label: "탭 삭제", action: () => {const live=current();if(live)deleteTabsBlockTab(live,tabId);} }] : []),
    { label: "취소", action: closeModal },
    { label: "저장", primary: true, action: () => {
      const live=current()?.props?.tabs?.find(item=>item.id===tabId);
      if(!live){setStatus('탭이 변경되었습니다. 현재 페이지에서 다시 열어 주세요.','error');return;}
      live.name = String($("#tabNameInput")?.value || live.name).trim().slice(0, 100) || live.name;
      closeModal();
      markDirty();
      captureEditorHistory(true);
      renderBlocks();
    } },
  ]);
  setTimeout(() => $("#tabNameInput")?.focus(), 0);
}

let SyncedReferenceViews = null, SyncedText = null, SyncedTextRenderDeferred = false;
let SyncedActionBindings = [];
const SyncedTextSlots = new Map();
function syncedTextScope() {
  return {realm:String(location.origin||''),data:State.pageData,userId:State.user?.id,pageId:State.activePageId,
    workspaceId:State.pageData?.page?.workspace_id,navigationSequence:State.navigation.sequence};
}
function syncedScopeCurrent(scope) {
  return scope.userId===State.user?.id&&scope.pageId===State.activePageId&&scope.data===State.pageData
    &&scope.workspaceId===State.pageData?.page?.workspace_id&&scope.navigationSequence===State.navigation.sequence;
}
const syncedSlotKey=(scope,id)=>JSON.stringify([scope.userId,scope.workspaceId,scope.pageId,id]);
function syncedTextHoldsFocus(root) {
  const target=document.activeElement?.closest?.('[data-synced-text]'),reference=target?.closest('[data-synced-reference]');
  if(!reference||!root.contains(reference)||!activePageCanEdit())return false;
  const slot=SyncedTextSlots.get(syncedSlotKey(syncedTextScope(),reference.dataset.syncedReference));
  const block=State.pageData?.blocks.find(item=>item.id===reference.dataset.syncedReference);
  return Boolean(slot&&syncedScopeCurrent(slot.scope)&&block&&JSON.stringify(block.props?.synced_from)===JSON.stringify(slot.origin));
}
function renderSyncedText(slot,view) {
  if(!slot.node.isConnected||!(slot.current?.()??syncedScopeCurrent(slot.scope))||view.origin.document_id!==slot.origin.document_id||view.origin.block_id!==slot.origin.block_id)return;
  const content=slot.node.querySelector('.synced-reference-content'),status=slot.node.querySelector('.synced-reference-status');
  if(!view.available){content.replaceChildren();slot.signature='';slot.node.querySelector('[data-synced-open]').hidden=true;const notice=slot.node.querySelector('.synced-text-status');if(notice)notice.hidden=true;status.hidden=false;status.textContent='원본이 없거나 접근할 수 없습니다. 작성한 입력은 이 브라우저에 보관했습니다.';return;}
  const signature=JSON.stringify(view.tree),focused=content.contains(document.activeElement);
  if(signature!==slot.signature&&!focused&&!view.composing){
    const presentation=window.NotionSyncedContent.capture(content);
    content.innerHTML=window.NotionSyncedContent.render(view.tree,{
      richHtml:blockRichHtml,fileUrl:slot.fileUrl||notionFileUrl,mathHtml:value=>window.NotionMath?.renderHtml(value),
      textEditor:(block,html)=>window.NotionSyncedText.types.has(block.type)
        ?`<span class="synced-text-editor" data-synced-text="${escapeAttr(block.id)}" data-synced-kind="${escapeAttr(block.type)}" role="textbox" aria-label="동기화된 글" aria-multiline="true" spellcheck="true">${html||'<br>'}</span>`:html,
    });
    window.NotionSyncedContent.bind(content);window.NotionSyncedContent.restore(content,presentation.length?presentation:slot.presentation);slot.signature=signature;
  }
  content.querySelectorAll('[data-synced-text]').forEach(editor=>{
    editor.contentEditable=String(view.editable);editor.setAttribute('aria-readonly',String(!view.editable));
    if(!view.editable&&editor===document.activeElement&&!view.busy)editor.blur();
  });
  status.hidden=true;
  let notice=slot.node.querySelector('.synced-text-status');
  if(!notice){
    notice=document.createElement('div');notice.className='synced-text-status';notice.setAttribute('role','status');
    notice.innerHTML='<span data-synced-save-label></span><button type="button" data-synced-save>다시 시도</button><button type="button" data-synced-rebase>내 입력 적용</button><button type="button" data-synced-discard>최신 내용 사용</button><details data-synced-conflicts><summary>변경 내용 비교</summary><div></div></details>';
    slot.node.querySelector('.synced-reference-actions').before(notice);
    for(const [selector,action] of [['[data-synced-save]','flush'],['[data-synced-rebase]','rebase'],['[data-synced-discard]','discard']]){
      notice.querySelector(selector).onclick=()=>void (slot.text||SyncedText)[action](slot.scope,slot.id,slot.origin).catch(error=>setStatus(error.message,'error'));
    }
  }
  notice.hidden=!view.dirty&&!view.error&&!view.parked;notice.dataset.error=String(Boolean(view.error||view.conflict));
  notice.querySelector('[data-synced-save-label]').textContent=(view.error||(view.conflict?'원본의 같은 글이 변경되었습니다. 입력을 보관했습니다.':view.busy?'저장 중…':view.composing?'입력 중…':view.dirty?'변경사항을 보관했습니다.':''))
    +(view.parked?' 이전 원본에서 작성한 입력을 따로 보관하고 있습니다. 그 원본으로 다시 연결되면 복구합니다.':'');
  notice.querySelector('[data-synced-save]').hidden=view.busy||view.composing||view.conflict||!view.dirty;
  notice.querySelector('[data-synced-rebase]').hidden=!view.conflict||view.pending||view.busy||view.composing||!view.editable;
  notice.querySelector('[data-synced-discard]').hidden=!view.dirty||view.pending||view.busy||view.composing;
  const compare=notice.querySelector('[data-synced-conflicts]'),items=compare.querySelector('div');
  compare.hidden=!view.differences.length;
  const differenceSignature=JSON.stringify(view.differences);
  if(compare.dataset.signature!==differenceSignature){
    items.replaceChildren();compare.dataset.signature=differenceSignature;
    for(const difference of view.differences){
      const item=document.createElement('p');
      item.textContent=`최신 내용: ${difference.latest===null?'이 글은 삭제되었습니다.':difference.latest}\n내 입력: ${difference.draft}`;
      items.append(item);
    }
  }
}
function syncedTextController() {
  if(SyncedText||!CollaborativeEditingOutbox)return SyncedText;
  SyncedText=window.NotionSyncedText.create({
    journal:CollaborativeEditingOutbox,current:syncedScopeCurrent,canEdit:()=>activePageCanEdit(),operationId:()=>navigationOperationId('synced-text'),
    send:(scope,id,body)=>api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/synced-blocks/${encodeURIComponent(id)}/text`,{method:'POST',body,cache:'no-store'}),
    changed:()=>SyncedReferenceViews.refresh(),
    state:(scope,id,view)=>{const slot=SyncedTextSlots.get(syncedSlotKey(scope,id));if(slot)renderSyncedText(slot,view);},
  });return SyncedText;
}
function bindSyncedTextInput(slot) {
  const content=slot.node.querySelector('.synced-reference-content');
  const text=()=>slot.text||SyncedText;
  const current=()=>slot.current?.()??syncedScopeCurrent(slot.scope);
  const field=event=>event.target.closest?.('[data-synced-text]');
  const capture=editor=>{
    const block={id:editor.dataset.syncedText,type:editor.dataset.syncedKind,content:'',props:{}};
    syncEditorBlock(editor,block);
    if(block.type==='code')delete block.props.rich_text_html;
    return text()?.draft(slot.scope,slot.id,{id:block.id,content:block.content,rich_text_html:block.props.rich_text_html??null},slot.origin);
  };
  const save=()=>{clearTimeout(slot.saveTimer);slot.saveTimer=setTimeout(()=>{if(current())void text()?.flush(slot.scope,slot.id,slot.origin);},650);};
  content.addEventListener('focusin',event=>{if(field(event)){if(slot.focus)slot.focus();else{clearBlockSelection();State.activeBlockId=slot.id;}}});
  content.addEventListener('click',event=>{
    // The summary marker still toggles; clicking its editable title places the
    // caret without also activating the summary's default disclosure action.
    if(field(event)?.closest('summary'))event.preventDefault();
  });
  content.addEventListener('compositionstart',event=>{const editor=field(event);if(!editor)return;event.stopPropagation();editor.dataset.imeComposing='true';text()?.composing(slot.scope,slot.id,true,slot.origin);});
  content.addEventListener('compositionend',event=>{const editor=field(event);if(!editor)return;event.stopPropagation();editor.dataset.imeComposing='false';capture(editor);text()?.composing(slot.scope,slot.id,false,slot.origin);save();});
  content.addEventListener('input',event=>{const editor=field(event);if(!editor)return;capture(editor);if(!event.isComposing&&editor.dataset.imeComposing!=='true')save();});
  content.addEventListener('focusout',()=>queueMicrotask(()=>{
    if(!current()||content.contains(document.activeElement))return;
    const view=text()?.snapshot(slot.scope,slot.id);if(view)renderSyncedText(slot,view);save();
    if(slot.afterBlur)slot.afterBlur();else if(!slot.text&&SyncedTextRenderDeferred)renderBlocks();
  }));
  content.addEventListener('keydown',event=>{
    const editor=field(event);if(!editor)return;
    event.stopPropagation();
    if(event.isComposing||event.keyCode===229||editor.dataset.imeComposing==='true')return;
    if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();capture(editor);void text()?.flush(slot.scope,slot.id,slot.origin);}
    if(event.key==='Escape'){event.preventDefault();editor.blur();slot.node.querySelector('[data-synced-locations]')?.focus();}
  });
  content.addEventListener('paste',event=>{
    const editor=field(event);if(!editor||editor.contentEditable!=='true')return;
    event.preventDefault();event.stopPropagation();
    if(window.NotionSyncedClipboard.read(event.clipboardData)){setStatus('동기화 블록은 페이지 본문의 빈 블록이나 블록 선택 위치에 붙여넣어 주세요.','error');return;}
    const html=event.clipboardData?.getData('text/html'),plain=event.clipboardData?.getData('text/plain')||'';
    if(html&&!['code','equation'].includes(editor.dataset.syncedKind))document.execCommand('insertHTML',false,sanitizeRichHtml(html));
    else document.execCommand('insertText',false,plain);
    capture(editor);save();
  });
}
async function flushSyncedText() {
  const bodyOk=await ItemBodyUi?.synced?.flush()??true;
  const ok=(await SyncedText?.flushPage(syncedTextScope())??true)&&bodyOk;
  if(!ok)setStatus('동기화된 글의 저장 또는 입력 상태를 먼저 확인해 주세요.','error');
  return ok;
}

function mountSyncedReferences(root) {
  SyncedActionBindings.forEach(binding=>binding.dispose());SyncedActionBindings=[];
  for(const slot of SyncedTextSlots.values())clearTimeout(slot.saveTimer);
  SyncedTextSlots.clear();
  if (!SyncedReferenceViews) {
    const current = syncedScopeCurrent;
    SyncedReferenceViews = window.NotionSyncedReferences.create({
      current,
      visible: slot => !document.hidden && (!slot || slot.node.isConnected && !slot.node.closest('[hidden]')),
      load: (scope, blockId, signal) => api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/synced-blocks/${encodeURIComponent(blockId)}`, {signal, cache: "no-store"}),
      watch: (scope, witness, notify) => window.NotionSyncedLive.watch({
        current, visible: () => !document.hidden,
        socket: (url, protocol) => new WebSocket(url, protocol),
        async issue(context, document, signal) {
          const clientId = `synced_${crypto.randomUUID().replaceAll('-', '')}`;
          const binding = await collaborationSessionBinding();
          if (signal.aborted || !current(context)) throw new Error('Obsolete synced observer');
          const ticket = await api(`/api/notion/workspaces/${encodeURIComponent(document.workspace_id)}/pages/${encodeURIComponent(document.document_id)}/realtime-ticket`, {
            method: 'POST', signal, cache: 'no-store',
            body: {client_id: clientId, session_binding_sha256: binding},
          });
          return {ticket, clientId, binding};
        },
      }, scope, witness, notify),
      display(slot, state) {
        const content = slot.node.querySelector('.synced-reference-content');
        const status = slot.node.querySelector('.synced-reference-status');
        const open = slot.node.querySelector('[data-synced-open]');
        if(state.phase==='ready')describeSyncedOriginal(slot.node,state.data);
        if(state.phase==='loading'&&content.childElementCount){slot.node.setAttribute('aria-busy','true');return;}
        if(state.phase==='ready'&&syncedTextController()){
          slot.node.setAttribute('aria-busy','false');open.hidden=false;
          void SyncedText.bind(slot.scope,slot.id,state.data);return;
        }
        if(state.phase==='error'||state.phase==='idle')SyncedText?.unavailable(slot.scope,slot.id);
        if (state.phase === 'loading' && content.childElementCount) slot.presentation = window.NotionSyncedContent.capture(content);
        if (state.phase === 'idle' || state.phase === 'error') delete slot.presentation;
        content.replaceChildren(); open.hidden = true;
        slot.node.setAttribute('aria-busy', String(state.phase === 'loading'));
        status.hidden = false;
        if (state.phase === 'ready') {
          if (state.data.tree && (state.data.tree.id !== state.data.origin.block_id
            || state.data.tree.type !== 'synced_block' || state.data.tree.props?.synced_from !== null)) throw new Error('Invalid synced tree');
          content.innerHTML = window.NotionSyncedContent.render(state.data.tree || {...state.data.block, children: []}, {
            richHtml: blockRichHtml, fileUrl: notionFileUrl, mathHtml: value => window.NotionMath?.renderHtml(value),
          });
          window.NotionSyncedContent.bind(content);
          window.NotionSyncedContent.restore(content, slot.presentation);
          status.textContent = '';
          status.hidden = true;
          open.hidden = false;
        } else {
          status.textContent = state.phase === 'loading' ? '동기화된 내용 불러오는 중…'
            : state.phase === 'error' ? state.denied ? '원본이 없거나 접근할 수 없습니다.' : '동기화된 내용을 불러오지 못했습니다. 다시 시도해 주세요.'
            : '동기화된 내용을 확인해 주세요.';
        }
      },
    });
    const refresh = () => { void SyncedReferenceViews.refresh(); };
    window.addEventListener('focus', refresh);
    document.addEventListener('visibilitychange', refresh);
    window.addEventListener('pagehide', () => SyncedReferenceViews.clear());
  }
  const data = State.pageData;
  const supported = data?.page?.collaborative_synced_read === true;
  const slots = [];
  root.querySelectorAll('[data-synced-reference]').forEach(node => {
    const block = data.blocks.find(item => item.id === node.dataset.syncedReference);
    const scope=syncedTextScope(),clipboardOrigin={...block.props.synced_from};
    SyncedActionBindings.push(window.NotionSyncedActions.bind(node,{
      ...syncedLocationsHost(scope,block.id,block.props.synced_from,{current:()=>syncedScopeCurrent(scope),copyCurrent:()=>syncedClipboardScopeCurrent(scope,block.id,clipboardOrigin),flush:flushSyncedText}),
      current:()=>syncedScopeCurrent(scope),
      identity:JSON.stringify([scope.realm,scope.userId,scope.workspaceId,scope.pageId,scope.navigationSequence,'main',block.id,block.props.synced_from]),
      more:activePageCanEdit()?button=>{
        if(!syncedScopeCurrent(scope)||!activePageCanEdit()||EditorHost.isComposing())return;
        const index=State.pageData.blocks.findIndex(item=>item.id===block.id);
        if(index<0||!window.NotionSyncedReferences.reference(State.pageData.blocks[index]))return;
        if(!$('#blockMenu').hidden&&BlockMenuReturnFocus===button)closeBlockMenu(true);
        else openBlockMenu(index,button,'actions');
      }:null,
    }));
    const retry = node.querySelector('[data-synced-refresh]');
    retry.hidden = !supported;
    if (!supported) {
      node.querySelector('.synced-reference-status').textContent = '이 페이지에서는 동기화 원본을 불러올 수 없습니다.';
      return;
    }
    const slot = {id: block.id, origin: block.props.synced_from, node,scope:syncedTextScope()};
    SyncedTextSlots.set(syncedSlotKey(slot.scope,slot.id),slot);
    bindSyncedTextInput(slot);
    retry.addEventListener('click', () => { void SyncedReferenceViews.refresh(); });
    node.querySelector('[data-synced-open]').addEventListener('click', () => {
      void (async()=>{if(!(await flushSyncedText())||!syncedScopeCurrent(slot.scope))return;const data=await api(`/api/notion/workspaces/${encodeURIComponent(slot.scope.workspaceId)}/pages/${encodeURIComponent(slot.scope.pageId)}/synced-blocks/${encodeURIComponent(slot.id)}`,{cache:'no-store'});if(syncedScopeCurrent(slot.scope)&&data.origin?.document_id===slot.origin.document_id&&data.origin?.block_id===slot.origin.block_id)await openSyncedOriginal(data);})().catch(error=>setStatus(error.message,'error'));
    });
    slots.push(slot);
  });
  if(supported)root.querySelectorAll('[data-synced-source]').forEach(node=>{
    const block=data.blocks.find(value=>value.id===node.dataset.syncedSource);
    if(!block||!window.NotionSyncedReferences.explicit(block)||window.NotionSyncedReferences.reference(block))return;
    const scope=syncedTextScope(),origin={document_id:scope.pageId,block_id:block.id},current=()=>syncedScopeCurrent(scope);
    const binding=window.NotionSyncedActions.bind(node,{
      ...syncedLocationsHost(scope,block.id,origin,{current,copyCurrent:()=>syncedClipboardScopeCurrent(scope,block.id,origin),flush:flushSyncedText}),source:true,current,
      identity:JSON.stringify([scope.realm,scope.userId,scope.workspaceId,scope.pageId,scope.navigationSequence,'main',block.id,origin]),
      more:activePageCanEdit()?button=>{if(current()&&activePageCanEdit()&&!EditorHost.isComposing()){
        const index=State.pageData.blocks.findIndex(value=>value.id===block.id);
        if(index>=0&&window.NotionSyncedReferences.explicit(State.pageData.blocks[index])&&!window.NotionSyncedReferences.reference(State.pageData.blocks[index]))openBlockMenu(index,button,'actions');
      }}:null,
    });
    node.querySelector('[data-synced-refresh]').onclick=()=>void SyncedReferenceViews.refresh();
    SyncedActionBindings.push(binding);
  });
  void SyncedReferenceViews.mount(syncedTextScope(), slots);
}

function describeSyncedLocation(entry){
  const samePage=entry.endpoint.document_id===State.activePageId;
  return {title:entry.body_title||entry.page_title||'제목 없음',detail:[entry.original?'원본':'',samePage?'이 페이지':entry.body_title?entry.page_title:'',
    entry.location.kind==='row'?'항목 본문':entry.location.kind==='template'?'템플릿 본문':''].filter(Boolean).join(' · ')};
}

function syncedClipboardPageCurrent(scope){
  return scope.realm===location.origin&&scope.userId===State.user?.id&&scope.pageId===State.activePageId
    &&scope.workspaceId===State.pageData?.page?.workspace_id&&scope.navigationSequence===State.navigation.sequence
    &&State.pageData?.page?.collaborative_synced_read===true;
}

function syncedClipboardScopeCurrent(scope,id,origin){
  // Copy carries only an endpoint, so an unchanged current main mount can take
  // over its own intent after an automatic redraw. Navigation, actor changes,
  // removed/hidden mounts and changed original endpoints still invalidate it.
  if(!syncedClipboardPageCurrent(scope)||EditorHost.isComposing())return false;
  const blocks=State.pageData.blocks.filter(block=>block.id===id),block=blocks[0];
  if(blocks.length!==1||!window.NotionSyncedReferences.explicit(block))return false;
  const endpoint=window.NotionSyncedReferences.reference(block)?block.props.synced_from:{document_id:scope.pageId,block_id:id};
  if(!window.NotionSyncedActions.sameEndpoint(endpoint,origin))return false;
  const row=document.querySelector(`#blocks > .block-row[data-block-id="${CSS.escape(id)}"]`);
  return Boolean(row?.isConnected&&!row.closest('[hidden]')&&row.querySelector('[data-synced-source-copy]'));
}

function syncedLocationsHost(scope,id,origin,host){
  const instance={document_id:scope.pageId,block_id:id};
  const url=`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/synced-blocks/${encodeURIComponent(id)}/locations`;
  return {instance,origin,describeLocation:describeSyncedLocation,copyCurrent:host.copyCurrent,
    copy:async activationCurrent=>{
      const current=()=>(host.copyCurrent?host.copyCurrent():host.current())&&activationCurrent()&&!EditorHost.isComposing();
      if(!current()||!(await host.flush())||!current())return;
      const data=await api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/synced-blocks/${encodeURIComponent(id)}`,{cache:'no-store'});
      if(!current())return;
      const descriptor=window.NotionSyncedClipboard.fromRead(data,instance,origin,location.origin);
      await window.NotionSyncedClipboard.copy(descriptor,{document,navigator,ClipboardItem:window.ClipboardItem,Blob,current});
      if(current())setStatus('복사 완료! 동기화하려는 페이지에 붙여넣어 주세요.','ok');
    },
    loadLocations:signal=>api(url,{signal,cache:'no-store'}),
    error:error=>setStatus(error.message,'error'),
    openLocation:async entry=>{
      if(!host.current()||!(await host.flush())||!host.current())return;
      const inventory=await api(url,{cache:'no-store'});if(!host.current())return;
      const entries=window.NotionSyncedActions.inventory(inventory,instance,origin);
      const selected=entries.find(value=>window.NotionSyncedActions.sameEndpoint(value.endpoint,entry.endpoint));
      const sourceEntry=entries.find(value=>value.original);
      if(!selected||selected.workspace_id!==entry.workspace_id||!window.NotionSyncedBodyView.sameLocation(selected.location,entry.location))throw Error('동기화 대상의 위치나 접근권한이 변경되었습니다. 다시 열어 주세요.');
      const value=await api(`/api/notion/workspaces/${encodeURIComponent(selected.workspace_id)}/pages/${encodeURIComponent(selected.endpoint.document_id)}/synced-blocks/${encodeURIComponent(selected.endpoint.block_id)}`,{cache:'no-store'});
      if(!host.current()||!window.NotionSyncedActions.sameEndpoint(value.instance,selected.endpoint)||!window.NotionSyncedActions.sameEndpoint(value.origin,origin)
          ||!window.NotionSyncedBodyView.sameLocation(value.locations?.instance,selected.location)
          ||!window.NotionSyncedBodyView.sameLocation(value.locations?.origin,sourceEntry.location))throw Error('동기화 대상 위치를 다시 확인해 주세요.');
      await openSyncedOriginal({origin:selected.endpoint,locations:{origin:selected.location},focus_reference:!selected.original,
        reference_origin:!selected.original?origin:null,reference_origin_location:!selected.original?sourceEntry.location:null});
    }};
}

function describeSyncedOriginal(node,data) {
  const samePage=data.origin.document_id===State.activePageId,kind=data.locations?.origin?.kind;
  window.NotionSyncedActions.describe(node,{
    title:samePage?(State.pageData?.page?.title||'제목 없음'):'원본 페이지',
    detail:['원본',samePage?'이 페이지':'',kind==='row'?'항목 본문':kind==='template'?'템플릿 본문':''].filter(Boolean).join(' · '),
  });
}

function observeSyncedDocument(current,context,witness,notify) {
  return window.NotionSyncedLive.watch({
      current,visible:()=>!document.hidden,socket:(url,protocol)=>new WebSocket(url,protocol),
      async issue(context,document,signal){
        const clientId=`synced_body_${crypto.randomUUID().replaceAll('-','')}`,binding=await collaborationSessionBinding();
        if(signal.aborted||!current(context))throw Error('Obsolete synced body observer');
        const ticket=await api(`/api/notion/workspaces/${encodeURIComponent(document.workspace_id)}/pages/${encodeURIComponent(document.document_id)}/realtime-ticket`,{
          method:'POST',signal,cache:'no-store',body:{client_id:clientId,session_binding_sha256:binding},
        });return {ticket,clientId,binding};
      },
    },context,witness,notify);
}

function syncedBodyView(scope,location,host) {
  if(!CollaborativeEditingOutbox||!window.NotionSyncedBodyView||State.pageData?.page?.collaborative_synced_read!==true)return null;
  const endpoint=(context,id)=>`/api/notion/workspaces/${encodeURIComponent(context.workspaceId)}/pages/${encodeURIComponent(context.pageId)}/synced-blocks/${encodeURIComponent(id)}`;
  const current=context=>host.current(context);
  const detachScope=id=>({userId:scope.userId,workspaceId:scope.workspaceId,pageId:scope.pageId,blockId:id});
  const detachEnabled=State.navigation?.collaborativeSyncedDetach===true&&Boolean(getSyncedDetachController());
  return window.NotionSyncedBodyView.create({
    ...host,scope,location,text:window.NotionSyncedText,references:window.NotionSyncedReferences,journal:CollaborativeEditingOutbox,
    identity:JSON.stringify([scope.realm,scope.userId,scope.workspaceId,scope.pageId,State.navigation.sequence,location]),
    changed:async(context,id,result)=>{
      if(current(context)&&State.activePageId===context.pageId&&result?.document_id===context.pageId
          &&Number.isSafeInteger(result.document_sequence)&&result.document_sequence>0){
        State.pageData.page.document_sequence=Math.max(Number(State.pageData.page.document_sequence||0),result.document_sequence);
        State.liveCollaboration.durableCursor=Math.max(Number(State.liveCollaboration.durableCursor||0),result.document_sequence);
      }
      await host.changed(context,id,result);
    },
    operationId:()=>navigationOperationId('synced-body-text'),
    load:(context,id,signal)=>api(endpoint(context,id),{signal,cache:'no-store'}),
    send:(context,id,body)=>api(endpoint(context,id)+'/text',{method:'POST',body,cache:'no-store'}),
    renderText:renderSyncedText,bindText:bindSyncedTextInput,error:error=>setStatus(error.message,'error'),
    describe:describeSyncedOriginal,
    locationHost:(id,origin,flush)=>syncedLocationsHost(scope,id,origin,{current:()=>current(scope),flush}),
    open:openSyncedOriginal,
    detachPending:id=>detachEnabled&&getSyncedDetachController().list(detachScope(id)).some(item=>item.blockId===id&&!item.confirmed),
    detach:detachEnabled?async(id,hooks)=>{
      const result=await getSyncedDetachController().run(detachScope(id),{
        ...hooks,current:()=>hooks.current()&&scope.userId===State.user?.id&&State.navigation?.collaborativeSyncedDetach===true,
        prepare:async()=>({...await hooks.prepare(),operation_id:navigationOperationId('detach-body')}),
      });
      if(current(scope)){
        if(result.state==='committed')setStatus(result.current.archived||result.current.body_archived?'해제된 본문이 현재 휴지통에 있습니다.':'동기화 해제가 저장되었습니다.','ok');
        else if(result.state==='stale')setStatus('원본이나 권한이 바뀌어 저장하지 않았습니다. 현재 내용을 확인한 뒤 다시 시도해 주세요.','error');
        else if(result.state==='busy')setStatus('다른 탭에서 같은 동기화 해제를 처리하고 있습니다. 잠시 후 결과를 확인해 주세요.','ok');
        else if(result.state==='unknown')setStatus('완료된 결과가 아직 없습니다. 같은 요청의 결과를 다시 확인해 주세요.','error');
      }
      return result;
    }:null,
    watch:(context,witness,notify)=>observeSyncedDocument(current,context,witness,notify),
  });
}

async function openDatabaseTemplateReadDialog(blockId,templateId) {
  const scope=linkedDatabaseScope(),block=State.pageData?.blocks.find(item=>item.id===blockId);
  if(!block||block.props?.linked_database||!collaborativeDatabaseActive())throw Error('템플릿 원본 위치를 확인할 수 없습니다.');
  const databaseId=String(block.props?.database_id||block.id);
  await reloadCanonicalDatabases([databaseId]);if(!linkedDatabaseScopeCurrent(scope))return;
  let database=State.pageData.databases.find(item=>item.id===databaseId);
  let template=database?.templates?.find(item=>item.id===templateId&&item.state==='active');
  if(!template||template.body_unavailable||template.default_unavailable)throw Error('템플릿 원본에 접근할 수 없습니다.');
  openModal('템플릿',`<div class="database-template-form">
    <div class="database-template-location" role="note">${iconSvg('table')}<span>${escapeHtml(database.title||'데이터베이스')}의 템플릿</span></div>
    <h2 id="dbTemplateReadName">${escapeHtml(template.name)}</h2>
    <div id="dbTemplateReadDefaults" class="database-template-defaults" aria-label="기본 속성값"></div>
    <section class="database-template-body" aria-label="본문"><div id="dbTemplateReadBody" class="database-template-body-editor"></div></section>
    <p id="dbTemplateReadStatus" role="status"></p></div>`,[]);
  const root=$('#dbTemplateReadBody'),name=$('#dbTemplateReadName'),defaults=$('#dbTemplateReadDefaults'),status=$('#dbTemplateReadStatus');
  let editor=null,synced=null,flight=null,disposed=false;
  const current=()=>{
    if(disposed||!root.isConnected)return false;
    if(!linkedDatabaseScopeCurrent(scope)){
      if(template)redact('템플릿 원본의 접근 상태가 변경되었습니다. 다시 열어 주세요.');
      return false;
    }
    return true;
  };
  const render=()=>{
    if(!current())return;
    name.textContent=template?.name||'';
    defaults.innerHTML=template?(database.properties||[]).map(property=>
      `<div class="database-template-default-row"><span class="database-template-property-name">${escapeHtml(property.name||property.id)}</span><span class="database-template-property-value">${escapeHtml(databaseDisplayValue(template.default_values?.[property.id])||'비어 있음')}</span></div>`).join(''):'';
    editor?.render(template?{ready:true,blocks:window.NotionDatabaseItemBody.normalize(template.body||[]),editable:false}:{ready:false,blocks:[],editable:false,error:status.textContent});
  };
  synced=syncedBodyView(scope,{kind:'template',database_id:databaseId,template_id:templateId},{
    current,editable:()=>false,fileUrl:fileId=>notionFileUrl(fileId,{workspaceId:scope.workspaceId,databaseId}),
    changed:()=>refresh(),state:render,
  });
  editor=window.NotionDatabaseItemEditor.create(root,{
    synced,core:EditorCore,escape:escapeHtml,sanitize:sanitizeRichHtml,html:blockRichHtml,sync:syncEditorBlock,
    blockOps:window.NotionDatabaseItemBlocks,interaction:window.NotionUiInteraction,style:window.NotionBlockStyle,
    tabs:window.NotionDatabaseItemTabs,resources:window.NotionDatabaseItemResources,
    fileUrl:fileId=>notionFileUrl(fileId,{workspaceId:scope.workspaceId,databaseId}),
    caret:caretOffset,setCaret:setCaretOffset,normalize:window.NotionDatabaseItemBody.normalize,equal:window.NotionDatabaseItemBody.equal,
    surface:$('#modalBg .modal'),scroller:$('#modalBody'),change:()=>false,save:async()=>true,composing:()=>{},discard:async()=>false,
  });
  render();
  function redact(message){
    if(disposed||!root.isConnected)return;
    // Scope loss must clear visible data too; a stale scope cannot authorize
    // rendering, but it must not prevent redaction of the already-open modal.
    template=null;name.textContent='';defaults.replaceChildren();status.textContent=message;
    editor?.render({ready:false,blocks:[],editable:false,error:message});synced?.clear();
  }
  async function refresh(){
    if(!current())return;if(flight)return flight;
    flight=(async()=>{
      try{
        await reloadCanonicalDatabases([databaseId]);if(!current())return;
        database=State.pageData.databases.find(item=>item.id===databaseId);
        const latest=database?.templates?.find(item=>item.id===templateId&&item.state==='active');
        if(!latest||latest.body_unavailable||latest.default_unavailable)throw Error('템플릿 원본에 접근할 수 없습니다.');
        template=latest;status.textContent='';render();
      }catch(error){redact([401,403,404].includes(error.status)?'템플릿 원본에 더 이상 접근할 수 없습니다.':error.message||'템플릿을 새로 읽지 못했습니다.');}
    })().finally(()=>{flight=null;});return flight;
  }
  const witness={workspace_id:scope.workspaceId,document_id:scope.pageId,
    document_sequence:State.pageData.page.document_sequence,workspace_epoch:State.pageData.page.workspace_epoch,
    document_epoch:State.pageData.page.document_epoch};
  const stop=observeSyncedDocument(current,scope,witness,event=>{
    if(event.type==='unavailable')redact('템플릿 원본의 접근권한을 확인하는 중입니다.');
    if(['changed','available','unavailable'].includes(event.type))void refresh();
  });
  const onRefresh=()=>void refresh();window.addEventListener('focus',onRefresh);document.addEventListener('visibilitychange',onRefresh);
  ActiveDatabaseTemplateEditor={readOnlyTemplate:{databaseId,templateId},dirty:()=>false,beforeClose:()=>true,
    syncedScope:scope,syncedBody:synced,
    dispose:()=>{disposed=true;stop?.();editor.dispose();window.removeEventListener('focus',onRefresh);document.removeEventListener('visibilitychange',onRefresh);},
  };
}

async function openSyncedOriginalReadDialog(endpoint,bodyLocation,referenceOrigin=null,referenceOriginLocation=null) {
  const scope=linkedDatabaseScope();
  if(scope.pageId!==endpoint.document_id||!collaborativeDatabaseActive()
      ||State.pageData.page.collaborative_synced_read!==true)throw Error('동기화 원본에 접근할 수 없습니다.');
  openModal('동기화 원본',`<section class="database-template-body">
    <div class="database-template-location" role="note">${iconSvg('table')}<span>${bodyLocation.kind==='row'?'항목':'템플릿'} 본문 · 보기 전용</span></div>
    <div id="syncedOriginalReadBody" class="synced-reference-content" aria-label="동기화 원본 본문"></div>
    <p id="syncedOriginalReadStatus" role="status"></p>
    <button type="button" id="syncedOriginalReadRefresh">새로고침</button></section>`);
  const root=$('#syncedOriginalReadBody'),status=$('#syncedOriginalReadStatus');
  let disposed=false,restoreFocus=true,presentation=[];
  const current=()=>{
    if(disposed||!root.isConnected)return false;
    if(!linkedDatabaseScopeCurrent(scope)){
      root.replaceChildren();status.textContent='원본의 접근 상태가 변경되었습니다. 다시 열어 주세요.';
      return false;
    }
    return true;
  };
  // Read the original endpoint itself. No synthetic owning block, local body
  // copy, write controller or inferred database/page grant is introduced.
  const views=window.NotionSyncedReferences.create({
    current,visible:()=>current()&&!document.hidden&&!$('#modalBg').hidden,
    load:async(context,id,signal)=>{
      const value=await api(`/api/notion/workspaces/${encodeURIComponent(context.workspaceId)}/pages/${encodeURIComponent(context.pageId)}/synced-blocks/${encodeURIComponent(id)}`,{signal,cache:'no-store'});
      if(!window.NotionSyncedBodyView.sameLocation(value?.locations?.instance,bodyLocation)
          ||!window.NotionSyncedBodyView.sameLocation(value?.locations?.origin,referenceOrigin?referenceOriginLocation:bodyLocation)
          ||!window.NotionSyncedActions.sameEndpoint(value.origin,referenceOrigin||endpoint)
          ||value.tree?.id!==(referenceOrigin||endpoint).block_id)throw Error('동기화 원본의 본문 위치가 변경되었습니다.');
      return value;
    },
    watch:(context,witness,notify)=>observeSyncedDocument(current,context,witness,notify),
    display(_slot,state){
      if(!root.isConnected)return;
      restoreFocus ||= root.contains(document.activeElement);
      if(root.childElementCount)presentation=window.NotionSyncedContent.capture(root);
      root.replaceChildren();status.hidden=false;
      if(state.phase==='ready'&&current()){
        root.innerHTML=window.NotionSyncedContent.render(state.data.tree,{
          richHtml:blockRichHtml,mathHtml:value=>window.NotionMath?.renderHtml(value),
          fileUrl:fileId=>notionFileUrl(fileId,{workspaceId:state.data.witnesses.find(value=>value.document_id===state.data.origin.document_id).workspace_id,databaseId:state.data.locations.origin.database_id}),
        });
        window.NotionSyncedContent.bind(root);window.NotionSyncedContent.restore(root,presentation);
        status.textContent='';status.hidden=true;
        if(restoreFocus){
          const target=root.querySelector(`[data-synced-node="${CSS.escape((referenceOrigin||endpoint).block_id)}"]`);
          if(target){target.tabIndex=0;target.focus({preventScroll:true});target.scrollIntoView({block:'center'});}
          restoreFocus=false;
        }
      }else status.textContent=state.phase==='loading'?'원본 불러오는 중…':state.denied?'원본이 없거나 접근할 수 없습니다.':'원본을 표시할 수 없습니다. 새로고침해 주세요.';
    },
  });
  const refresh=()=>void views.refresh({afterFlight:true});
  $('#syncedOriginalReadRefresh').onclick=refresh;
  window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh);
  ActiveDatabaseTemplateEditor={readOnlyOriginal:{endpoint:structuredClone(endpoint),location:structuredClone(bodyLocation)},dirty:()=>false,beforeClose:()=>true,
    dispose:()=>{views.dispose();disposed=true;window.removeEventListener('focus',refresh);document.removeEventListener('visibilitychange',refresh);},
  };
  await views.mount(scope,[{id:endpoint.block_id,origin:referenceOrigin||endpoint}]);
}

async function openSyncedOriginal(data) {
  const endpoint=data?.origin,location=data?.locations?.origin;
  if(!endpoint?.document_id||!endpoint.block_id||!location)throw Error('동기화 원본 위치를 확인할 수 없습니다.');
  const templateEditor=ActiveDatabaseTemplateEditor;
  if(templateEditor?.beforeNavigate){
    if(!(await templateEditor.beforeNavigate())||ActiveDatabaseTemplateEditor!==templateEditor)return;
  }else if(templateEditor?.beforeClose?.()===false)return;
  if(templateEditor)closeModal(true);
  if(State.activePageId!==endpoint.document_id){
    await openPage(endpoint.document_id);
    const load=State.pageLoadSequence;
    // Initial collaborative replay redraws the item projection. Open its
    // body only after replay, otherwise that redraw can remove the target focus.
    for(let attempt=0;attempt<1200&&State.activePageId===endpoint.document_id
        &&State.pageLoadSequence===load&&collaborativeEditingActive()&&!State.liveCollaboration.crdtReady;attempt++){
      await new Promise(resolve=>setTimeout(resolve,25));
    }
    if(State.pageLoadSequence!==load||State.activePageId!==endpoint.document_id)return;
    if(collaborativeEditingActive()&&!State.liveCollaboration.crdtReady)throw Error('원본 페이지의 연결을 확인하지 못했습니다. 다시 시도해 주세요.');
  }
  if(State.activePageId!==endpoint.document_id)return;
  let root=$('#blocks');
  if(location.kind!=='page'){
    const block=State.pageData.blocks.find(item=>!item.props?.linked_database
      &&DATABASE_BLOCK_TYPES.has(item.type)&&String(item.props?.database_id||item.id)===location.database_id);
    if(!block){
      if(!['row','template'].includes(location.kind))throw Error('원본의 본문 종류를 확인할 수 없습니다.');
      if(!(await closeSidePeek(false)))return;
      await openSyncedOriginalReadDialog(endpoint,location,data.reference_origin,data.reference_origin_location);return;
    }
    if(location.kind==='row'){
      await openOwnedDatabaseItem(block.id,location.row_id);root=ItemBodyUi?.slot;
    }else if(location.kind==='template'){
      if(!(await closeSidePeek(false)))return;
      if(canEditDatabaseSchema()&&activePageCanEdit()){
        await openDatabaseTemplateDialog(block.id,location.template_id);root=$('#dbTemplateBodyEditor');
      }else{await openDatabaseTemplateReadDialog(block.id,location.template_id);root=$('#dbTemplateReadBody');}
    }else throw Error('원본의 본문 종류를 확인할 수 없습니다.');
  }else if(!(await closeSidePeek(false)))return;
  const navigation=State.navigation.sequence;
  for(let attempt=0;attempt<120;attempt++){
    if(State.activePageId!==endpoint.document_id||State.navigation.sequence!==navigation)return;
    if(location.kind==='row'){
      const model=LinkedDatabaseItems?.snapshot();
      if(!model||model.scope.itemKind!=='owned'||model.rowId!==location.row_id
          ||model.data.source.database_id!==location.database_id||model.scope.pageId!==endpoint.document_id)return;
      // A current projection can replace the body slot during its first read.
      // Rebind only within the same authorized row rather than focusing old DOM.
      root=ItemBodyUi?.slot;
    }
    if(!root?.isConnected){await new Promise(resolve=>setTimeout(resolve,25));continue;}
    const target=root.querySelector(data.focus_reference?
      `[data-synced-reference="${CSS.escape(endpoint.block_id)}"] [data-synced-actions-menu]`:
      `[data-body-text="${CSS.escape(endpoint.block_id)}"],[data-block-id="${CSS.escape(endpoint.block_id)}"] [contenteditable]`);
    if(target){
      if(!target.isContentEditable)target.tabIndex=0;
      target.scrollIntoView({block:'center'});target.focus({preventScroll:true});
      // An in-flight property read can temporarily make the body inert.
      // A focus call then has no effect, so wait for the current surface.
      if(document.activeElement===target){
        if(location.kind==='row'&&LinkedItemPeekUi){LinkedItemPeekUi.focus=null;LinkedItemPeekUi.restoreFocus=false;}
        return;
      }
    }
    await new Promise(resolve=>setTimeout(resolve,25));
  }
  setStatus('원본 위치는 열었지만 해당 블록을 찾지 못했습니다. 새로고침해 주세요.','error');
}

function linkedDatabaseScope() {
  return {realm:String(location.origin||''),data:State.pageData,pageId:State.activePageId,userId:State.user?.id,
    workspaceId:State.navigation.workspaceId,navigationSequence:State.navigation.sequence,
    pageLoadSequence:State.pageLoadSequence};
}

function linkedDatabaseScopeCurrent(scope) {
  return scope.data === State.pageData && scope.pageId === State.activePageId
    && scope.userId === State.user?.id && scope.workspaceId === State.navigation.workspaceId
    && scope.navigationSequence === State.navigation.sequence;
}

function personalLinkedScopeCurrent(scope) {
  return Boolean(scope && scope.pageId===State.activePageId
    && scope.userId===State.user?.id && scope.workspaceId===State.navigation.workspaceId
    && scope.navigationSequence===State.navigation.sequence
    && scope.pageLoadSequence===State.pageLoadSequence);
}

let LinkedDatabaseViews = null, PersonalLinkedViews = null, LinkedDatabaseCells = null, LinkedDatabaseRows = null, LinkedDatabaseTemplates = null, LinkedDatabaseItems = null, IndependentDatabaseCells = null, IndependentDatabaseRows = null, OwnedDatabaseCells = null, OwnedRowIcons = null, OwnedRowDuplicate = null, OwnedRowMove = null, OwnedRowToPage = null, PageToRowReturn = null;
let DatabaseRowMoveStatusGeneration = 0;
const TimelineHourScrollRestores = new Map();
let OwnedItemBody = null, ItemBodyUi = null, OwnedItemAppearance = null, ItemAppearanceUi = null;
let IndependentDatabaseItemBodyEditor = null;
let IndependentDatabaseItemBody = null;
let IndependentItemComments = null, IndependentItemCommentsUi = null;
let ItemComments = null, ItemCommentsUi = null;
const LINKED_ITEM_EDITABLE_TYPES = new Set(['title','text','rich_text','number','checkbox','select','status','multi_select','date','url','email','phone','person','files']);
let LinkedItemPeekUi = null;

function linkedItemVisibleRows(block) {
  const linkedRoot=document.querySelector(`[data-linked-database="${CSS.escape(block.id)}"]`),linked=Boolean(linkedRoot);
  const root=linkedRoot||document.querySelector(`[data-block-id="${CSS.escape(block.id)}"]`);
  if(!root)return visibleDatabaseRows(block);
  const rows=databaseRows(block),seen=new Set(),visible=[];
  const buttons=[...root.querySelectorAll(linked?'[data-linked-row-id]':'[data-table-row],[data-calendar-row]')];
  const auxiliary=button=>Boolean(button.closest?.('[data-undated]'));
  for(const button of [...buttons.filter(button=>!auxiliary(button)),...buttons.filter(auxiliary)]){
    const id=linked?button.dataset.linkedRowId:rows[Number(button.dataset.tableRow??button.dataset.calendarRow)]?._canonical_row_id;
    if(!id||seen.has(id))continue;
    const index=rows.findIndex(row=>String(row._canonical_row_id)===id);
    if(index>=0){seen.add(id);visible.push({item:rows[index],index});}
  }
  return visible;
}

function linkedItemController() {
  if(LinkedDatabaseItems)return LinkedDatabaseItems;
  const cells=scope=>scope.itemKind==='owned'?ownedCellController():linkedCellController();
  LinkedDatabaseItems=window.NotionLinkedDatabaseItems.create({
    current:linkedDatabaseScopeCurrent,
    canEdit:(scope,data)=>Boolean(CollaborativeEditingOutbox)&&linkedDatabaseScopeCurrent(scope)&&activePageCanEdit()
      &&window.NotionLinkedDatabaseCells.editable(data),
    rows:databaseRows,visibleRows:linkedItemVisibleRows,properties:databaseProperties,
    fieldEditable:property=>LINKED_ITEM_EDITABLE_TYPES.has(property.type),
    value:(property,value,item)=>DatabaseBridge.cellValue(property,{...item,[property.id]:value}),
    change:(scope,block,values)=>cells(scope).change(scope,block,values),
    status:(scope,block)=>cells(scope).status(scope,block),
    retry:(scope,block)=>cells(scope).retry(scope,block),discard:(scope,block)=>cells(scope).discard(scope,block),
    history:(scope,block,delta)=>delta<0?cells(scope).undo(scope,block):cells(scope).redo(scope,block),
    error:window.NotionLinkedDatabaseCells.errorMessage,
    hasBody:state=>state.scope.itemKind==='owned'&&(state.data.database?.capabilities?.row_content===true||state.data.database?.capabilities?.row_appearance===true),
    saveBody:saveDatabaseItemBody,
    beforeSave:async state=>{
      if(ItemBodyUi?.scope===state.scope&&ItemBodyUi.row===state.rowId&&ItemBodyUi.paste?.pending()){
        setStatus('동기화 붙여넣기 결과를 먼저 확인해 주세요.','error');return false;
      }
      if(ItemBodyUi?.scope===state.scope&&ItemBodyUi.row===state.rowId&&!(await ItemBodyUi.synced?.flush()??true))return false;
      return beforeDatabaseItemCommentsLeave(state);
    },
    bodyPending:state=>Boolean(ItemBodyUi?.scope===state.scope&&ItemBodyUi.row===state.rowId&&ItemBodyUi.synced?.pending())||ItemComments?.pending(databaseItemCommentContext(state))||OwnedItemBody?.pending(state.scope,state.data.source.database_id,state.rowId)||OwnedItemAppearance?.pending(state.scope,state.data.source.database_id,state.rowId),
    modeChanged:updateDatabaseItemRoute,
    closed:state=>{if(state?.mode==='full')clearDatabaseItemRoute(state);},
    openSource:page=>openPage(page),render:renderLinkedItemPeek,
    restoreFocus:state=>{
      const root=document.querySelector(state.scope.itemKind==='owned'
        ? `[data-block-id="${CSS.escape(state.blockId)}"]` : `[data-linked-database="${CSS.escape(state.blockId)}"]`);
      const index=databaseRows(state.block).findIndex(row=>row._canonical_row_id===state.rowId);
      const selector=state.scope.itemKind==='owned'?`[data-table-row="${index}"],[data-calendar-row="${index}"]`:`[data-linked-row-id="${CSS.escape(state.rowId)}"]`;
      const target=root?.querySelector(selector)||(state.returnFocus?.isConnected?state.returnFocus:null)||root?.querySelector('[role="grid"]')||$('#workspaceMain');
      target?.focus({preventScroll:true});
    },
  });return LinkedDatabaseItems;
}

function databaseItemCommentContext(model){
  const source=model.data.source,witness=model.data.witnesses?.find(item=>item.document_id===source.document_id);
  return {realm:model.scope.realm,userId:model.scope.userId,workspaceId:witness?.workspace_id||model.scope.workspaceId,
    pageId:source.document_id,databaseId:source.database_id,rowId:model.rowId,blockId:model.blockId,host:model.scope};
}

function beforeDatabaseItemCommentsLeave(model){
  const context=databaseItemCommentContext(model);
  return model.unavailable?(ItemComments?.park(context)??true):(ItemComments?.beforeLeave(context)??true);
}

function databaseItemCommentWitness(model){
  const source=model.data.source.document_id,witness=model.data.witnesses?.find(item=>item.document_id===source);
  return JSON.stringify([witness,model.data.database?.effective_role,model.data.database?.capabilities?.row_comments]);
}

function itemCommentBase(context){
  return `/api/notion/workspaces/${encodeURIComponent(context.workspaceId)}/pages/${encodeURIComponent(context.pageId)}/comments`;
}

function itemCommentsController(){
  if(ItemComments)return ItemComments;
  ItemComments=window.NotionDatabaseItemComments.create({
    journal:CollaborativeEditingOutbox,
    exclusive:(name,work)=>navigator.locks?navigator.locks.request(name,work):work(),
    current:context=>{
      const model=itemAppearanceCurrent(context.host,context.databaseId,context.rowId);
      return Boolean(model?.item&&!model.unavailable);
    },
    operationId:()=>`item-comment-${crypto.randomUUID().replaceAll('-','')}`,
    commentId:()=>`item-comment-${crypto.randomUUID().replaceAll('-','')}`,
    mentions:commentMentionSubjectIds,
    read:context=>api(`${itemCommentBase(context)}?database_id=${encodeURIComponent(context.databaseId)}&row_id=${encodeURIComponent(context.rowId)}`),
    send:(context,request)=>api(itemCommentBase(context)+(request.action==='create'?'':`/${encodeURIComponent(request.comment)}`)+(request.action==='react'?'/reactions':''),
      {method:request.action==='delete'?'DELETE':['create','react'].includes(request.action)?'POST':'PATCH',body:request.body}),
    prepare:()=>LinkedDatabaseItems.save(),
    changed:async(context,result)=>{
      if(context.host.itemKind==='owned')await refreshOwnedDatabaseItem(context.host,context.blockId,result);
      else await LinkedDatabaseViews?.refresh(true);
      void loadInboxItems(false);
    },
    error:window.NotionLinkedDatabaseCells.errorMessage,
    state:(context,value)=>{if(ItemCommentsUi?.context===context)ItemCommentsUi.view.render(value);},
  });return ItemComments;
}

function syncDatabaseItemComments(model,body){
  const root=body.querySelector('[data-item-comments]');
  if(!root||!model.item||!CollaborativeEditingOutbox){ItemCommentsUi?.view.dispose();ItemCommentsUi=null;return;}
  const context=databaseItemCommentContext(model),controller=itemCommentsController();
  const witness=databaseItemCommentWitness(model);
  const same=ItemCommentsUi?.root===root&&ItemCommentsUi.context.host===context.host
    &&window.NotionDatabaseItemComments.identity(ItemCommentsUi.context)===window.NotionDatabaseItemComments.identity(context);
  if(same){
    const ui=ItemCommentsUi;ui.view.render(controller.snapshot(ui.context));
    if(ui.witness!==witness){ui.witness=witness;void controller.refresh(ui.context);}return;
  }
  ItemCommentsUi?.view.dispose();
  const view=window.NotionDatabaseItemCommentsView.create(root,{
    snapshot:()=>controller.snapshot(context),draft:value=>controller.draft(context,value),
    submit:()=>{const draft=controller.snapshot(context)?.draft;return controller.mutate(context,draft.editing?'edit':'create',draft.editing);},
    mutate:(action,id,value)=>controller.mutate(context,action,id,value),
    canEdit:item=>controller.canEdit(context,item),composing:value=>controller.composing(context,value),
    retry:()=>controller.retry(context),discard:()=>controller.discard(context),refresh:()=>controller.refresh(context),
    person:id=>[State.user,...State.users].find(user=>user?.id===id)?.display_name||id,
    people:()=>[State.user,...State.users].filter((user,index,all)=>user?.id&&all.findIndex(other=>other?.id===user.id)===index),
  });
  ItemCommentsUi={context,root,view,witness};void controller.bind(context);
}

function itemAppearanceCurrent(scope,database,row){
  const model=LinkedDatabaseItems?.snapshot();
  return model&&model.scope===scope&&model.data.source.database_id===database&&model.rowId===row&&linkedDatabaseScopeCurrent(scope)?model:null;
}

function itemAppearanceController(){
  if(OwnedItemAppearance)return OwnedItemAppearance;
  OwnedItemAppearance=window.NotionDatabaseItemAppearance.create({
    journal:CollaborativeEditingOutbox,current:linkedDatabaseScopeCurrent,canEdit:scope=>linkedDatabaseScopeCurrent(scope)&&activePageCanEdit(),
    operationId:()=>`item-appearance-${crypto.randomUUID().replaceAll('-','')}`,
    send:(scope,body)=>api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/databases/commands`,{method:'POST',body}),
    changed:refreshOwnedDatabaseItem,error:window.NotionLinkedDatabaseCells.errorMessage,
    state:(scope,database,row,value)=>renderDatabaseItemAppearanceState(scope,database,row,value),
  });return OwnedItemAppearance;
}

function renderDatabaseItemAppearanceState(scope,database,row,value){
  const model=itemAppearanceCurrent(scope,database,row),ui=ItemAppearanceUi;if(!model||!ui||ui.scope!==scope||ui.row!==row||ui.database!==database)return;
  ui.view.render(value);
  const blocked=model.busy||Boolean(model.status.pending)||value.busy||value.pending||!value.ready;
  const active=document.activeElement;
  if(blocked&&!ui.blocked&&LinkedItemPeekUi.body.contains(active)){
    const selection=window.getSelection();ui.focus={element:active,start:active.selectionStart,end:active.selectionEnd,range:selection?.rangeCount?selection.getRangeAt(0).cloneRange():null};
  }
  LinkedItemPeekUi.body.inert=blocked;LinkedItemPeekUi.body.setAttribute('aria-busy',String(value.busy||model.busy));
  if(!blocked&&ui.blocked&&ui.focus){
    const focus=ui.focus;ui.focus=null;
    if(focus.element.isConnected&&!focus.element.disabled&&(active===document.body||active===focus.element)){
      focus.element.focus({preventScroll:true});
      if(focus.start!=null&&focus.element.setSelectionRange)focus.element.setSelectionRange(focus.start,focus.end);
      else if(focus.range&&focus.element.contains(focus.range.startContainer)){const selection=window.getSelection();selection.removeAllRanges();selection.addRange(focus.range);}
    }
  }
  ui.blocked=blocked;
  const crumb=LinkedItemPeekUi.root.querySelector('[data-linked-item-crumb]');
  if(crumb&&!crumb.hidden)crumb.innerHTML=`/ ${value.appearance.icon?pageIconHtml(value.appearance.icon,'item-crumb-icon'):''}<span>${escapeHtml(databaseRowTitle(model.block,model.item||{}))}</span>`;
}

async function saveDatabaseItemAppearance(scope,database,row,updates){
  try{
    let model=itemAppearanceCurrent(scope,database,row);if(!model||model.scope.itemKind!=='owned')return false;
    const controller=itemAppearanceController();
    if(controller.snapshot(scope,database,row)?.pending)throw Error('보관한 모양 변경을 다시 저장하거나 지운 뒤 선택해 주세요.');
    if(!(await LinkedDatabaseItems.save())||!itemAppearanceCurrent(scope,database,row))return false;
    const data=ownedItemData(State.pageData.blocks.find(block=>block.id===model.blockId));if(!data)return false;
    await controller.bind(scope,model.blockId,data,row);
    if(!itemAppearanceCurrent(scope,database,row))return false;
    return await controller.set(scope,database,row,updates);
  }catch(error){if(itemAppearanceCurrent(scope,database,row))setStatus(error.message,'error');return false;}
}

async function openDatabaseItemIcon(scope,database,row,anchor){
  try{
    const model=itemAppearanceCurrent(scope,database,row),value=OwnedItemAppearance?.snapshot(scope,database,row);if(!model||!value?.editable||value.pending)return;
    await window.NotionIcons.load();if(!itemAppearanceCurrent(scope,database,row))return;
    const customEmojiAvailable = await workspaceCustomEmojiAvailable(scope.workspaceId);
    if(!itemAppearanceCurrent(scope,database,row))return;
    openModal('항목 아이콘','<div id="itemIconPicker"></div>');$('#modalBg').classList.add('icon-picker-modal');let picker;
    const current=()=>itemAppearanceCurrent(scope,database,row)&&!$('#modalBg').hidden&&ActiveIconPicker===picker;
    picker=window.NotionIcons.mount($('#itemIconPicker'),{
      loadUrl:loadIconImageUrl,
      customEmoji:customEmojiAvailable?customEmojiPickerHost(scope.workspaceId,current):null,
      recentScope:State.user?.id,
      value:value.appearance.icon,
      save:async icon=>{if(!current())throw Error('항목이 변경되었습니다.');if(!(await saveDatabaseItemAppearance(scope,database,row,{icon})))throw Error(OwnedItemAppearance.snapshot(scope,database,row)?.error||'보관한 모양 변경의 저장을 확인해 주세요.');},
      upload:async(file,signal)=>{
        if(!current()||!(await LinkedDatabaseItems.save())||!current())throw Error('항목의 저장 상태를 확인해 주세요.');
        const id=await uploadPageIcon(file,scope.pageId,signal,{item:true});
        if(!current())throw Error('항목이 변경되었습니다.');await refreshOwnedDatabaseItem(scope,model.blockId);return id;
      },
      close:()=>{if(!current())return;closeModal();ItemAppearanceUi?.slot.querySelector('[data-item-appearance="icon"]')?.focus({preventScroll:true});},
    });ActiveIconPicker=picker;ModalReturnFocus=anchor;anchorCurrentModal(anchor);
  }catch(error){if(itemAppearanceCurrent(scope,database,row))setStatus(error.message,'error');}
}

async function openDatabaseItemCover(scope,database,row,anchor){
  const value=OwnedItemAppearance?.snapshot(scope,database,row);if(!itemAppearanceCurrent(scope,database,row)||!value?.editable||value.pending)return;
  const choices=window.NotionDatabaseItemAppearanceView.covers;
  let saving=false;
  const apply=async cover=>{
    if(saving||!itemAppearanceCurrent(scope,database,row))return;saving=true;
    const dialog=$('#modalBg'),error=$('#itemCoverError');error.textContent='커버 저장 중…';
    const buttons=[...dialog.querySelectorAll('[data-item-cover-choice],.modal-actions button')];buttons.forEach(button=>button.disabled=true);
    try{const saved=await saveDatabaseItemAppearance(scope,database,row,{cover});if(!error.isConnected)return;
      if(saved){closeModal();ItemAppearanceUi?.slot.querySelector('[data-item-appearance="cover"]')?.focus({preventScroll:true});}
      else error.textContent=OwnedItemAppearance.snapshot(scope,database,row)?.error||'저장을 확인하지 못했습니다. 창을 닫고 보관한 변경을 다시 저장해 주세요.';
    }finally{saving=false;buttons.forEach(button=>button.disabled=false);}
  };
  openModal('항목 커버',`<div class="cover-picker">${choices.map((cover,index)=>`<button type="button" data-item-cover-choice="${index}" aria-label="커버 색상 ${index+1}" style="background:${escapeAttr(cover)}"></button>`).join('')}</div><label class="cover-url-label">이미지 URL<input id="itemCoverUrl" type="url" value="${escapeAttr(/^https?:/.test(value.appearance.cover)?value.appearance.cover:'')}" placeholder="https://example.com/cover.jpg"></label><p id="itemCoverError" role="status"></p>`,[
    {label:'취소',action:closeModal},{label:'URL 적용',primary:true,action:async()=>{const url=safeExternalUrl($('#itemCoverUrl')?.value||'');if(!/^https?:\/\//.test(url)){$('#itemCoverError').textContent='이미지의 http 또는 https 주소를 입력해 주세요.';return;}await apply(url);}},
  ]);
  ModalReturnFocus=anchor;
  $('#modalBg').querySelectorAll('[data-item-cover-choice]').forEach(button=>button.onclick=()=>void apply(choices[Number(button.dataset.itemCoverChoice)]));
}

function syncDatabaseItemAppearance(model,body){
  const slot=body.querySelector('[data-item-appearance]');
  if(!slot||model.unavailable){ItemAppearanceUi?.view.dispose();ItemAppearanceUi=null;return;}
  const scope=model.scope,database=model.data.source.database_id,row=model.rowId,owned=scope.itemKind==='owned'&&model.data.database.capabilities?.row_appearance===true;
  if(!ItemAppearanceUi||ItemAppearanceUi.slot!==slot||ItemAppearanceUi.scope!==scope||ItemAppearanceUi.database!==database||ItemAppearanceUi.row!==row){
    ItemAppearanceUi?.view.dispose();const controller=owned?itemAppearanceController():null;
    const view=window.NotionDatabaseItemAppearanceView.create(slot,LinkedItemPeekUi.appearanceNotice,{
      iconHtml:pageCustomIconContentHtml,url:value=>{const url=safeExternalUrl(value);return /^https?:\/\//.test(url)?url:'';},
      icon:anchor=>openDatabaseItemIcon(scope,database,row,anchor),cover:anchor=>openDatabaseItemCover(scope,database,row,anchor),
      save:updates=>saveDatabaseItemAppearance(scope,database,row,updates),retry:()=>controller?.flush(scope,database,row),discard:()=>controller?.discard(scope,database,row),
    });ItemAppearanceUi={slot,scope,database,row,view};
    const source=model.data.database.rows.find(item=>item.id===row);
    renderDatabaseItemAppearanceState(scope,database,row,{appearance:window.NotionDatabaseItemAppearance.normalize(source?.appearance),ready:!owned,editable:false});
    if(owned)void controller.bind(scope,model.blockId,model.data,row);
  }else if(owned)OwnedItemAppearance.update(scope,database,row,model.data);
  if(!owned)renderDatabaseItemAppearanceState(scope,database,row,{appearance:window.NotionDatabaseItemAppearance.normalize(model.data.database.rows.find(item=>item.id===row)?.appearance),ready:true,editable:false});
}

function itemBodyController() {
  if(OwnedItemBody)return OwnedItemBody;
  OwnedItemBody=window.NotionDatabaseItemBody.create({
    journal:CollaborativeEditingOutbox,current:linkedDatabaseScopeCurrent,
    canEdit:scope=>linkedDatabaseScopeCurrent(scope)&&activePageCanEdit(),
    operationId:()=>`item-body-${crypto.randomUUID().replaceAll('-','')}`,
    send:(scope,body)=>api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/databases/commands`,{method:'POST',body}),
    changed:async(scope,block,result)=>{
      await refreshOwnedDatabaseItem(scope,block,result);
      if(linkedDatabaseScopeCurrent(scope)&&ItemBodyUi?.scope===scope)await ItemBodyUi.synced?.refresh();
    },error:window.NotionLinkedDatabaseCells.errorMessage,
    state:(scope,database,row,value)=>{
      if(ItemBodyUi&&ItemBodyUi.scope===scope&&ItemBodyUi.database===database&&ItemBodyUi.row===row){
        ItemBodyUi.editor.render(value);
        const chooser=ItemBodyUi.slot.parentElement?.querySelector('[data-db-empty-template]');
        if(chooser)chooser.hidden=!value?.ready||!value.editable||value.busy||value.dirty||value.pending
          ||Boolean(value.blocks?.length);
      }
    },
  });return OwnedItemBody;
}

async function saveDatabaseItemBody(state) {
  if(ItemBodyUi?.scope===state.scope&&!(await ItemBodyUi.synced?.flush()??true))return false;
  if(state.scope.itemKind==='owned'&&!(await OwnedItemAppearance?.flush(state.scope,state.data.source.database_id,state.rowId)??true))return false;
  if(state.scope.itemKind!=='owned'||state.data.database?.capabilities?.row_content!==true)return true;
  const data=ownedItemData(State.pageData.blocks.find(block=>block.id===state.blockId));
  if(!data)return false;
  const controller=itemBodyController();await controller.bind(state.scope,state.blockId,data,state.rowId);
  return controller.flush(state.scope,data.source.database_id,state.rowId);
}

let SyncedOwnerLocations=null;
function syncedOwnerLocations(){
  if(!SyncedOwnerLocations){
    SyncedOwnerLocations=window.NotionSyncedOwnerScope.create({
      current:linkedDatabaseScopeCurrent,
      resolve:(scope,databaseId,signal)=>api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/database-sources/${encodeURIComponent(databaseId)}`,{signal,cache:'no-store'}),
      changed:(scope,blockId)=>{const model=LinkedDatabaseItems?.snapshot();if(model?.scope===scope&&model.blockId===blockId)renderLinkedItemPeek(model);},
    });
    window.addEventListener('pagehide',()=>SyncedOwnerLocations.clear());
  }
  return SyncedOwnerLocations;
}

function syncDatabaseItemBody(model,body) {
  const slot=body.querySelector('[data-item-content]');
  if(!slot||!model||model.unavailable){ItemBodyUi?.editor.dispose();ItemBodyUi=null;return;}
  const database=model.data.source.database_id,row=model.rowId,scope=model.scope;
  const owner=syncedOwnerLocations().get(scope,model.blockId,model.data);
  const ownerDocument=owner?.phase==='ready'?owner.documentId:'',ownerWorkspace=owner?.phase==='ready'?owner.workspaceId:'';
  const ownerKey=JSON.stringify([ownerWorkspace,ownerDocument]);
  const owned=scope.itemKind==='owned'&&model.data.database.capabilities?.row_content===true;
  if(!ItemBodyUi||ItemBodyUi.slot!==slot||ItemBodyUi.scope!==scope||ItemBodyUi.database!==database||ItemBodyUi.row!==row||ItemBodyUi.ownerKey!==ownerKey){
    ItemBodyUi?.editor.dispose();
    const controller=owned?itemBodyController():null;
    let editor,paste;
    const opened=()=>LinkedDatabaseItems?.snapshot();
    const current=()=>{
      const live=opened();return ItemBodyUi?.slot===slot&&ItemBodyUi?.scope===scope&&ItemBodyUi.row===row&&ItemBodyUi.ownerKey===ownerKey
        &&linkedDatabaseScopeCurrent(scope)&&live?.scope===scope&&!live.unavailable
        &&live.data.source.database_id===database&&syncedOwnerLocations().get(scope,model.blockId,live.data)?.documentId===ownerDocument;
    };
    // Endpoints/journals belong to the physical owner, while lifecycle and
    // visible-page editability remain bound to the opened linked instance.
    const ownerScope=ownerDocument===scope.pageId&&ownerWorkspace===scope.workspaceId?scope:
      {...scope,pageId:ownerDocument,workspaceId:ownerWorkspace};
    const renderState=()=>{
      if(!current())return;
      if(owned){const value=controller?.snapshot(scope,database,row);if(value)editor?.render(value);}
      else{const live=opened(),item=live.data.database.rows.find(item=>item.id===row);editor?.render({ready:true,blocks:item?.body?.blocks||[],editable:false});}
    };
    const refreshBody=async result=>{
      if(!current())return;
      if(owned)await refreshOwnedDatabaseItem(scope,model.blockId,result?.document_id===scope.pageId?result:undefined);
      else await LinkedDatabaseViews?.refresh(true);
    };
    const pasteEditable=()=>{
      if(!current()||State.pageData?.page?.collaborative_synced_read!==true||opened()?.composing
          ||synced?.pending()||EditorHost.isComposing())return false;
      if(State.pageData.page.collaborative_editing===true&&(State.liveCollaboration.initialReplay||!State.liveCollaboration.writeAuthorized))return false;
      if(owned){const value=controller?.snapshot(scope,database,row);return Boolean(value?.ready&&value.editable&&!value.pending&&!value.busy&&!value.composing);}
      const live=opened();return Boolean(live.editable&&!live.busy&&!live.status.pending);
    };
    if(ownerDocument&&ownerWorkspace&&State.pageData?.page?.collaborative_synced_read===true){
      paste=window.NotionSyncedRowClipboard.create({realm:scope.realm,userId:scope.userId,
        workspaceId:ownerWorkspace,pageId:ownerDocument,databaseId:database,rowId:row},{
        storage:()=>window.localStorage,locks:()=>navigator.locks,transport:api,current,
        editable:pasteEditable,changed:renderState,
      });
    }
    const finishPaste=async outcome=>{
      if(!current())return;
      if(outcome.state==='committed'){
        await refreshBody(outcome.result);
        if(!current())return;
        const item=opened()?.data.database.rows.find(item=>item.id===row);
        if(!item||item.version<outcome.result.target_version)throw Error('저장은 완료됐지만 최신 본문을 확인하지 못했습니다. 결과 확인을 다시 눌러 주세요.');
        if(!(await paste.acknowledge(outcome.result.operation_id)))throw Error('붙여넣기 결과 확인을 다시 눌러 주세요.');
        renderState();editor?.selectReference(outcome.result.reference_id);
        setStatus('동기화 블록을 항목 본문에 붙여넣었습니다.','ok');
      }else if(outcome.state==='stale')setStatus('원본이나 항목이 변경되어 붙여넣지 않았습니다. 최신 본문을 확인해 주세요.','error');
      else if(outcome.state==='busy')setStatus('다른 창에서 이 항목의 붙여넣기를 확인 중입니다.','error');
    };
    const pasteReference=async(encoded,target)=>{
      try{
        if(!paste||!pasteEditable()||paste.pending())throw Error('붙여넣을 항목과 저장 상태를 확인해 주세요.');
        const descriptor=window.NotionSyncedClipboard.decode(encoded,location.origin);
        const outcome=await paste.run({current:()=>current()&&target.current(),prepare:async()=>{
          if(!(await LinkedDatabaseItems.save())||!current()||!target.current())throw Error('항목 입력을 먼저 저장해 주세요.');
          const live=opened(),item=live.data.database.rows.find(item=>item.id===row);
          const fence=await api(`/api/notion/workspaces/${encodeURIComponent(ownerWorkspace)}/pages/${encodeURIComponent(ownerDocument)}/databases/${encodeURIComponent(database)}/rows/${encodeURIComponent(row)}/synced-paste-target`,{cache:'no-store'});
          if(!current()||!target.current()||fence?.contract!=='code_assist.notion.synced_row_clipboard.v1.target'
              ||fence.workspace_id!==ownerWorkspace||fence.document_id!==ownerDocument||fence.database_id!==database||fence.row_id!==row
              ||fence.expected_target_version!==item?.version)throw Error('항목이 변경되었습니다. 최신 본문을 확인한 뒤 다시 붙여넣어 주세요.');
          const empty=!item.body?.blocks?.length;
          return {source:descriptor.source,anchor_id:empty?null:target.anchorId,replace_empty:empty?false:target.replaceEmpty,
            expected_target_version:fence.expected_target_version,expected_workspace_epoch:fence.expected_workspace_epoch,
            expected_document_epoch:fence.expected_document_epoch,expected_database_epoch:fence.expected_database_epoch,
            operation_id:navigationOperationId('synced-row-paste')};
        }});
        await finishPaste(outcome);
      }catch(error){if(current())setStatus(error.message,'error');}
    };
    const retryPaste=async()=>{
      try{if(paste)await finishPaste(await paste.run({current,prepare:async()=>{throw Error('보관한 붙여넣기 요청이 없습니다.');}}));}
      catch(error){if(current())setStatus(error.message,'error');}
    };
    const synced=ownerDocument&&ownerWorkspace?syncedBodyView(ownerScope,{kind:'row',database_id:database,row_id:row},{
      current,editable:()=>{
        if(!current()||paste?.pending())return false;
        if(owned){const value=controller?.snapshot(scope,database,row);return Boolean(value?.editable&&!value.dirty&&!value.pending&&!value.busy&&!value.composing);}
        const live=opened();return Boolean(live.editable&&!live.busy&&!live.status.pending&&!live.composing);
      },
      fileUrl:fileId=>notionFileUrl(fileId,databaseFileScope(model.data.source,ownerWorkspace)),
      changed:(_scope,_id,result)=>refreshBody(result),
      accept:async data=>{
        const live=opened(),sequence=owned?Number(State.pageData?.page?.document_sequence||0):Number(live?.data.access?.document_sequence||live?.data.witnesses?.find(item=>item.document_id===ownerDocument)?.document_sequence||0);
        const witness=data.witnesses?.find(item=>item.document_id===ownerDocument);
        if(witness?.document_sequence>sequence)await refreshBody();
      },
      state:renderState,
    }):null;
    editor=window.NotionDatabaseItemEditor.create(slot,{
      synced,
      syncedPaste:paste?{snapshot:()=>paste.snapshot(),paste:pasteReference,retry:retryPaste}:null,
      core:EditorCore,escape:escapeHtml,sanitize:sanitizeRichHtml,html:blockRichHtml,sync:syncEditorBlock,
      blockOps:window.NotionDatabaseItemBlocks,interaction:window.NotionUiInteraction,style:window.NotionBlockStyle,
      tabs:window.NotionDatabaseItemTabs,
      resources:window.NotionDatabaseItemResources,
      fileUrl:fileId=>{
        const opened=LinkedDatabaseItems?.snapshot();
        const source=opened?.scope===scope&&opened?.rowId===row
          ?opened.data?.source:model.data.source;
        return notionFileUrl(fileId,databaseFileScope(source,scope.workspaceId));
      },
      clipboard:window.NotionBlockClipboard,clipboardSource:()=>({origin:location.origin,pageId:scope.pageId}),
      uploadResource:async(file,signal)=>{
        const current=()=>ItemBodyUi?.scope===scope&&ItemBodyUi.database===database&&ItemBodyUi.row===row&&linkedDatabaseScopeCurrent(scope);
        if(!owned||!current()||!(await LinkedDatabaseItems.save())||!current()||signal.aborted)throw Error('항목의 저장 상태를 확인해 주세요.');
        const uploaded=await uploadPageResource(file,scope.pageId,signal,{item:true});
        if(!current()||signal.aborted)throw Error('항목이 변경되었습니다.');
        await refreshOwnedDatabaseItem(scope,model.blockId);
        if(!current()||signal.aborted)throw Error('항목이 변경되었습니다.');
        return uploaded;
      },
      caret:caretOffset,setCaret:setCaretOffset,normalize:window.NotionDatabaseItemBody.normalize,equal:window.NotionDatabaseItemBody.equal,
      change:blocks=>controller?.draft(scope,database,row,blocks)||false,
      save:()=>LinkedDatabaseItems?.save(),
      composing:value=>controller?.composing(scope,database,row,value),
      discard:()=>controller?.discard(scope,database,row),
    });
    ItemBodyUi={slot,scope,database,row,editor,synced,paste,ownerScope,ownerKey};
    if(owned)void controller.bind(scope,model.blockId,model.data,row);
  }else if(owned)OwnedItemBody.update(scope,database,row,model.data);
  if(!owned){const item=model.data.database.rows.find(item=>item.id===row);ItemBodyUi.editor.render({ready:true,blocks:item?.body?.blocks||[],editable:false});}
}

async function applyDatabaseTemplateToEmptyItem(scope, blockId, databaseId, rowId, templateId) {
  if(!linkedDatabaseScopeCurrent(scope)||!activePageCanEdit())return;
  const current=LinkedDatabaseItems?.snapshot();
  if(current?.scope!==scope||current.rowId!==rowId||current.blockId!==blockId||!current.editable)return;
  const body=itemBodyController().snapshot(scope,databaseId,rowId);
  if(!body?.ready||body.dirty||body.pending||body.busy||body.blocks?.length){
    setStatus('본문 입력을 저장한 뒤 템플릿을 선택해 주세요.','error');return;
  }
  if(current.drafts.size&&!(await LinkedDatabaseItems.save())){
    setStatus('속성 입력을 저장한 뒤 템플릿을 선택해 주세요.','error');return;
  }
  if(!linkedDatabaseScopeCurrent(scope))return;
  const block=State.pageData.blocks.find(item=>item.id===blockId),data=ownedItemData(block);
  const row=data?.database?.rows?.find(item=>item.id===rowId);
  if(!row||!data.database.templates?.some(item=>item.id===templateId&&item.state==='active')){
    setStatus('템플릿이나 항목이 변경되었습니다. 다시 열어 주세요.','error');return;
  }
  try{
    const result=await sendCollaborativeDatabaseCommand({database_id:databaseId,
      command_kind:'database.row.template.apply',target_id:rowId,
      payload:{template_id:templateId},expected_target_version:row.version},
    `db-template-apply-${crypto.randomUUID().replaceAll('-','')}`);
    if(!linkedDatabaseScopeCurrent(scope))return;
    await refreshOwnedDatabaseItem(scope,blockId,result);
    if(linkedDatabaseScopeCurrent(scope))setStatus('템플릿을 항목에 적용했습니다.','ok');
  }catch(error){if(linkedDatabaseScopeCurrent(scope))setStatus('템플릿 적용 실패: '+error.message,'error');}
}

function databaseItemRoute() {
  const params=new URLSearchParams(location.search);
  return params.get('item_view')==='full'&&params.get('item_db')&&params.get('item_row')
    ? {database:params.get('item_db'),row:params.get('item_row')} : null;
}

function clearDatabaseItemRoute(state) {
  const route=databaseItemRoute();if(!route||route.database!==state.data.source.database_id||route.row!==state.rowId)return;
  const url=new URL(location.href);for(const key of ['item_db','item_row','item_view'])url.searchParams.delete(key);
  history.replaceState({pageId:state.scope.pageId},'',url.pathname+url.search+url.hash);
}

function updateDatabaseItemRoute(state,push) {
  if(state.mode!=='full'){clearDatabaseItemRoute(state);return;}
  const url=new URL(location.href);url.searchParams.set('item_db',state.data.source.database_id);url.searchParams.set('item_row',state.rowId);url.searchParams.set('item_view','full');
  history[push?'pushState':'replaceState']({pageId:state.scope.pageId},'',url.pathname+url.search+url.hash);
}

async function openDatabaseItemFull() {
  const model=LinkedDatabaseItems?.snapshot();if(!model)return;
  if(model.scope.itemKind==='owned'){await LinkedDatabaseItems.mode(model.mode==='full'?'side':'full');return;}
  const source=model.data.source,row=model.rowId;
  if(!(await LinkedDatabaseItems.close(false)))return;
  await openPage(source.document_id);
  if(State.activePageId!==source.document_id)return;
  const block=State.pageData.blocks.find(item=>(item.props?.database_id||item.id)===source.database_id);
  if(block){await openOwnedDatabaseItem(block.id,row);await LinkedDatabaseItems?.mode('full');}
}

function ownedDatabaseItemRouteBlock(route,pageData) {
  if(!route||!pageData)return null;
  const databases=new Map((pageData.databases||[]).map(item=>[String(item.id||''),item]));
  const matches=(pageData.blocks||[]).filter(block=>{
    if(block.props?.linked_database)return false;
    const database=databases.get(String(block.props?.database_id||block.id||''));
    return database?.rows?.some(row=>String(row.id||'')===route.row);
  });
  return matches.find(block=>String(block.props?.database_id||block.id||'')===route.database)
    ||(matches.length===1?matches[0]:null);
}

async function restoreDatabaseItemRoute(route=databaseItemRoute()) {
  if(!route||!State.pageData)return;
  const block=ownedDatabaseItemRouteBlock(route,State.pageData);
  if(!block){
    const sourceData=State.pageData,sourcePageId=State.activePageId;
    const workspaceId=State.navigation?.workspaceId;
    if(!State.navigation?.collaborativeSharing||!workspaceId){
      setStatus('데이터베이스 항목을 찾을 수 없습니다.','error');return;
    }
    let target;
    try{target=await api(`/api/notion/workspaces/${encodeURIComponent(workspaceId)}`
      +`/database-rows/${encodeURIComponent(route.row)}/location`);}
    catch{if(State.pageData===sourceData)setStatus('데이터베이스 항목을 찾을 수 없습니다.','error');return;}
    if(State.pageData!==sourceData||State.activePageId!==sourcePageId
        ||State.navigation.workspaceId!==workspaceId)return;
    if(target?.contract!=='code_assist.notion.database_row_location.v1'
        ||target.workspace_id!==workspaceId||target.row_id!==route.row
        ||!target.document_id){
      setStatus('데이터베이스 항목을 찾을 수 없습니다.','error');return;
    }
    const original=location.pathname+location.search+location.hash;
    const next=new URL(location.href);
    next.pathname=new URL(pageUrl(target.document_id)).pathname;
    if(target.placement==='page'){
      if(target.document_id!==route.row){
        setStatus('데이터베이스 항목을 찾을 수 없습니다.','error');return;
      }
      for(const name of ['item_db','item_row','item_view'])next.searchParams.delete(name);
      history.replaceState({pageId:target.document_id},'',next.pathname+next.search+next.hash);
      const loadSequence=State.pageLoadSequence;
      await openPage(target.document_id,false,PageFocusPolicy.PRESERVE);
      if(State.activePageId!==target.document_id&&State.pageLoadSequence===loadSequence+1){
        history.replaceState({pageId:sourcePageId},'',original);
        setStatus('이동한 페이지를 열지 못했습니다.','error');
      }
      return;
    }
    if(!target.database_id||target.document_id===sourcePageId){
      setStatus('데이터베이스 항목을 찾을 수 없습니다.','error');return;
    }
    next.searchParams.set('item_db',target.database_id);
    next.searchParams.set('item_row',route.row);
    next.searchParams.set('item_view','full');
    history.replaceState({pageId:target.document_id},'',next.pathname+next.search+next.hash);
    const loadSequence=State.pageLoadSequence;
    await openPage(target.document_id,false,PageFocusPolicy.PRESERVE);
    if(State.activePageId!==target.document_id&&State.pageLoadSequence===loadSequence+1){
      history.replaceState({pageId:sourcePageId},'',original);
      setStatus('이동한 데이터베이스 항목을 열지 못했습니다.','error');
    }
    return;
  }
  await openOwnedDatabaseItem(block.id,route.row);
  if(LinkedDatabaseItems?.snapshot()?.rowId===route.row)await LinkedDatabaseItems.mode('full',false);
}

function ownedItemData(block) {
  if(!block || block.props?.linked_database)return null;
  const database=State.pageData?.databases?.find(item=>item.id===(block.props?.database_id||block.id));
  if(!database)return null;
  return {source:{document_id:State.activePageId,database_id:database.id},database,
    witnesses:[{document_id:State.activePageId,workspace_id:State.navigation.workspaceId,
      document_sequence:currentDatabaseDocumentSequence(),workspace_epoch:State.pageData.page.workspace_epoch,
      document_epoch:State.pageData.page.document_epoch}]};
}

function syncOwnedDatabaseItem() {
  const model=LinkedDatabaseItems?.snapshot();
  if(model?.scope.itemKind!=='owned')return false;
  if(!linkedDatabaseScopeCurrent(model.scope)){LinkedDatabaseItems.invalidate();return true;}
  const block=State.pageData.blocks.find(item=>item.id===model.blockId),data=ownedItemData(block);
  if(!data){LinkedDatabaseItems.unavailable(model.scope,model.blockId,'데이터베이스가 삭제되었거나 접근할 수 없습니다.');return true;}
  LinkedDatabaseItems.update(model.scope,model.blockId,block,data);
  void ownedCellController().bind(model.scope,model.blockId,data);
  return true;
}

async function refreshOwnedDatabaseItem(scope,blockId,result,acknowledgedCells=[]) {
  if(!linkedDatabaseScopeCurrent(scope))return;
  const block=State.pageData.blocks.find(item=>item.id===blockId),data=ownedItemData(block);
  if(!data)return syncOwnedDatabaseItem();
  if(result?.document_sequence>0){
    State.pageData.page.document_sequence=Math.max(Number(State.pageData.page.document_sequence||0),result.document_sequence);
    State.liveCollaboration.durableCursor=Math.max(Number(State.liveCollaboration.durableCursor||0),result.document_sequence);
    if(result.command_kind==='database.row.content.set'){
      const row=data.database.rows.find(item=>item.id===result.target_id);
      if(row&&result.body&&row.version<=result.target_version){row.body=structuredClone(result.body);row.version=result.target_version;}
    }
    if(result.command_kind==='database.row.appearance.set'){
      const row=data.database.rows.find(item=>item.id===result.target_id);
      if(row&&row.version<=result.target_version){row.appearance=structuredClone(result.appearance);row.version=result.target_version;}
    }
    // The write is already confirmed. Keep its values if the following read fails.
    for(const cell of acknowledgedCells){
      const row=data.database.rows.find(item=>item.id===cell.row_id);
      const receipt=result.cells.find(item=>item.row_id===cell.row_id&&item.property_id===cell.property_id);
      if(row&&receipt&&Number(row.cell_versions?.[cell.property_id]||0)<=receipt.target_version){
        row.cells[cell.property_id]=structuredClone(cell.value);row.cell_versions[cell.property_id]=receipt.target_version;
      }
    }
    State.pageData.blocks=DatabaseBridge.applyCanonicalDatabases(State.pageData.blocks,State.pageData.databases);
    PageMetadataSync?.activity?.({subject_id:scope.userId,workspace_id:scope.workspaceId},scope.pageId);
  }
  try{await reloadCanonicalDatabases([data.source.database_id]);}
  catch(error){
    if([401,403,404].includes(error?.status)&&linkedDatabaseScopeCurrent(scope)){
      if(LinkedDatabaseItems?.snapshot()?.blockId===blockId)LinkedDatabaseItems.invalidate();
      setStatus('항목에 더 이상 접근할 수 없습니다. 페이지 권한을 확인해 주세요.','error');return;
    }
    if(linkedDatabaseScopeCurrent(scope))setStatus((result?'변경은 저장했지만 ':'')+'최신 보기를 불러오지 못했습니다. 새로고침해 주세요.','error');
  }
  if(linkedDatabaseScopeCurrent(scope))renderBlocks();
}

function ownedCellController() {
  if(OwnedDatabaseCells)return OwnedDatabaseCells;
  OwnedDatabaseCells=window.NotionLinkedDatabaseCells.createOwned({
    journal:CollaborativeEditingOutbox,current:linkedDatabaseScopeCurrent,
    canEdit:scope=>linkedDatabaseScopeCurrent(scope)&&collaborativeDatabaseActive()&&activePageCanEdit(),
    operationId:()=>`owned-cell-${crypto.randomUUID().replaceAll('-','')}`,
    send:(scope,block,body)=>{
      if(body.source.document_id!==scope.pageId)throw Error('항목의 데이터베이스 위치가 변경되었습니다.');
      const witness=body.source_witness;
      return api(`/api/notion/workspaces/${encodeURIComponent(scope.workspaceId)}/pages/${encodeURIComponent(scope.pageId)}/databases/commands`,{method:'POST',body:{
        database_id:body.source.database_id,target_id:body.source.database_id,command_kind:'database.cells.set',payload:{cells:body.cells},
        expected_document_sequence:witness.document_sequence,expected_workspace_epoch:witness.workspace_epoch,
        expected_document_epoch:witness.document_epoch,operation_id:body.operation_id}});
    },
    changed:refreshOwnedDatabaseItem,
    state:(scope,block,status)=>LinkedDatabaseItems?.status(scope,block,status),
  });return OwnedDatabaseCells;
}

