async function refreshOwnedRowMove(scope,blockId,result) {
  if(!linkedDatabaseScopeCurrent(scope))return;
  State.pageData.page.document_sequence=Math.max(Number(State.pageData.page.document_sequence||0),result.document_sequence);
  State.liveCollaboration.durableCursor=Math.max(Number(State.liveCollaboration.durableCursor||0),result.document_sequence);
  PageMetadataSync?.activity?.({subject_id:scope.userId,workspace_id:scope.workspaceId},scope.pageId);
  if(result.destination_document_id!==scope.pageId)PageMetadataSync?.activity?.(
    {subject_id:scope.userId,workspace_id:scope.workspaceId},result.destination_document_id);
  try {
    await reloadCanonicalDatabases(result.destination_document_id===scope.pageId
      ? [result.source_database_id,result.destination_database_id]
      : [result.source_database_id]);
    if(linkedDatabaseScopeCurrent(scope))renderBlocks();
  } catch(error) {
    if(linkedDatabaseScopeCurrent(scope))setStatus('이동은 저장했지만 최신 보기를 불러오지 못했습니다. 새로고침해 주세요.','error');
  }
  if(linkedDatabaseScopeCurrent(scope))void renderDatabaseRowMoveStatus();
}

