  root.hidden=false;document.body.classList.add('linked-item-open');syncSidePeekMobileTrigger();
  const full=model.mode==='full';root.classList.toggle('item-full-page',full);document.body.classList.toggle('item-full-page-open',full);$('#workspaceMain').inert=full;
  if(full)root.style.setProperty('--item-full-left',`${$('#workspaceMain').getBoundingClientRect().left}px`);
