  const sourceButton=root.querySelector('[data-linked-item-source]');sourceButton.hidden=!full;
  const sourceTitle=State.pageData?.page?.title||'',databaseTitle=model.data.database.title||'원본 데이터베이스';
  sourceButton.textContent=full?[sourceTitle,databaseTitle].filter((value,index,array)=>value&&array.indexOf(value)===index).join(' / '):'';
