function databaseSettingsDialogTarget(block) {
  const scope = databaseControlFocusScope(), blockId = block.id;
  const databaseId = String(block.props?.database_id || block.id);
  const viewId = activeDatabaseView(block)?.id;
  return () => {
    const current = State.pageData?.blocks?.find(item => item.id === blockId);
    if (scope !== databaseControlFocusScope() || !activePageCanEdit() || !canEditDatabaseSchema()
        || !current || !DATABASE_BLOCK_TYPES.has(current.type)
        || String(current.props?.database_id || current.id) !== databaseId
        || window.NotionLinkedDatabases.reference(current)
        || current.props?.active_view_id !== viewId
        || !current.props?.views?.some(view => view.id === viewId)) {
      setStatus("데이터베이스나 보기가 변경되었습니다. 설정을 다시 여세요.", "error");
      return null;
    }
    return current;
  };
}

function databaseDialogPropertiesExist(block, rules) {
  const ids = new Set(databaseProperties(block).map(property => property.id));
  if (rules.every(rule => ids.has(rule.property))) return true;
  setStatus("선택한 속성이 변경되었습니다. 설정을 다시 여세요.", "error");
  return false;
}

function openDatabasePropertyList(blockIndex) {
  const block = State.pageData?.blocks?.[blockIndex];
  if (!block || !canEditDatabaseSchema() || !activePageCanEdit()) return;
  const resolve = databaseSettingsDialogTarget(block);
  const visibility = Object.fromEntries(databaseProperties(block).map(property => [property.id, databasePropertyVisible(block, property)]));
  openModal("속성 표시", databaseProperties(block).map(property => `<label class="property-visibility-row"><span>${escapeHtml(property.name)}</span><input type="checkbox" data-visible-property="${escapeAttr(property.id)}" ${visibility[property.id] ? "checked" : ""} ${property.type === "title" ? "disabled" : ""}></label>`).join(""), [
    {label: "취소", action: closeModal}, {label: "저장", primary: true, action: () => {
      const current = resolve();
      if (!current) return;
      const properties = databaseProperties(current);
      const changes = [...$("#modalBody").querySelectorAll("[data-visible-property]")]
        .filter(input => input.checked !== visibility[input.dataset.visibleProperty]);
      if (!databaseDialogPropertiesExist(current, changes.map(input => ({property: input.dataset.visibleProperty})))) return;
      const next = {...(current.props.property_visibility || {})};
      changes.forEach(input => {
        const property = properties.find(item => item.id === input.dataset.visibleProperty);
        next[property.id] = property.type === "title" || input.checked;
      });
      current.props.property_visibility = next;
      syncActiveDatabaseView(current); markDirty(); captureEditorHistory(true); closeModal(); renderBlocks();
    }}
  ]);
}

