  $("#sidePeekShareSearch").addEventListener("keydown", event => {
    const holder = State.sidePeek, session = holder.sharePopover;
    if (!session || !sidePeekShareIsCurrent(holder, session)) return;
    if (["ArrowDown", "ArrowUp"].includes(event.key) && session.matches?.length && session.suggestionsOpen) {
      event.preventDefault();
      const offset = event.key === "ArrowDown" ? 1 : -1;
      session.highlight = (session.highlight + offset + session.matches.length) % session.matches.length;
      renderSidePeekShareCandidates(holder, session);
    } else if (event.key === "Enter") {
      if (session.selected) { event.preventDefault(); void mutateSidePeekShare(holder, session, "add"); }
      else if (session.matches?.length && session.suggestionsOpen) {
        event.preventDefault();
        selectSidePeekShareCandidate(holder, session, session.matches[session.highlight]);
      }
    } else if (event.key === "Escape" && session.suggestionsOpen && !$("#sidePeekShareSuggestions").hidden) {
      event.preventDefault();
      event.stopPropagation();
      session.suggestionsOpen = false;
      renderSidePeekShareCandidates(holder, session);
    }
  });
